INSERT INTO chapter_content (chapter_slug, subject_id, chapter_number, title, answers_json) VALUES ('telangana-economy-chapter-16-quick-facts', 'telangana-economy-en', 16, 'Quick Facts', '[{"a":"Rangareddy","e":"Rangareddy led with Rs. 3,41,080 crore, followed by Hyderabad, Medchal-Malkajgiri, Sangareddy, and Nalgonda.","table":{"headers":["Rank","District","GDDP Current Prices (Rs. crore)"],"rows":[["1","Rangareddy","3,41,080"],["2","Hyderabad","2,25,860"],["3","Medchal-Malkajgiri","1,16,133"],["4","Sangareddy","74,194"],["5","Nalgonda","64,219"]],"unit":"Rs. crore, 2024-25 (FRE)"}},{"a":"Mulugu","e":"Mulugu had the lowest GDDP at Rs. 11,943 crore, followed by Jayashankar and Kumuram Bheem.","table":{"headers":["Rank","District","GDDP Current Prices (Rs. crore)"],"rows":[["33","Mulugu","11,943"],["32","Jayashankar","16,413"],["31","Kumuram Bheem","16,465"]],"unit":"Rs. crore, 2024-25 (FRE)"}},{"a":"Rangareddy","e":"Rangareddy topped with Rs. 11,29,735, more than double the second-ranked Hyderabad.","table":{"headers":["Rank","District","Per Capita Income (Rs.)"],"rows":[["1","Rangareddy","11,29,735"],["2","Hyderabad","4,76,679"],["3","Sangareddy","3,94,587"],["4","Medchal-Malkajgiri","3,81,506"],["5","Bhadradri Kothagudem","3,69,420"]],"unit":"Rs., Current Prices, 2024-25 (FRE)"}},{"a":"Hanumakonda","e":"Hanumakonda had the lowest per capita income at Rs. 2,37,809, followed by Jagtial and Mahabubabad.","table":{"headers":["Rank","District","Per Capita Income (Rs.)"],"rows":[["33","Hanumakonda","2,37,809"],["32","Jagtial","2,44,245"],["31","Mahabubabad","2,56,485"]],"unit":"Rs., Current Prices, 2024-25 (FRE)"}},{"a":"Rangareddy","e":"Rangareddy led with 24,26,243, followed closely by Hyderabad, then Nizamabad, Medchal-Malkajgiri, and Sangareddy.","table":{"headers":["Rank","District","Total Population"],"rows":[["1","Rangareddy","24,26,243"],["2","Hyderabad","39,43,323"],["3","Medchal-Malkajgiri","24,60,095"],["4","Nizamabad","15,71,022"],["5","Sangareddy","15,27,301"]],"unit":"Number of persons, 2011 Census"}},{"a":"Mulugu","e":"Mulugu had the lowest population at 2,94,671, followed by Jayashankar and Kumuram Bheem.","table":{"headers":["Rank","District","Total Population"],"rows":[["33","Mulugu","2,94,671"],["32","Jayashankar","4,16,763"],["31","Kumuram Bheem","5,15,812"]],"unit":"Number of persons, 2011 Census"}},{"a":"Medchal-Malkajgiri","e":"Medchal-Malkajgiri recorded the highest literacy rate at 87.43% (male figure cited for ranking consistency; total rate 82.48%), closely followed by Hyderabad.","table":{"headers":["Rank","District","Total Literacy Rate (%)"],"rows":[["1","Hyderabad","83.25"],["2","Medchal-Malkajgiri","82.48"],["3","Rangareddy","71.88"],["4","Hanumakonda","74.13"],["5","Karimnagar","69.16"]],"unit":"%, Total Literacy Rate, 2011 Census"}},{"a":"Jogulamba Gadwal","e":"Jogulamba Gadwal had the lowest literacy rate at 49.87%, followed closely by Narayanpet and Kumuram Bheem.","table":{"headers":["Rank","District","Total Literacy Rate (%)"],"rows":[["33","Jogulamba Gadwal","49.87"],["32","Narayanpet","49.91"],["31","Kumuram Bheem","56.72"]],"unit":"%, Total Literacy Rate, 2011 Census"}},{"a":"Rangareddy","e":"Rangareddy led with 14.39 lakh, followed by Nagarkurnool, Nalgonda, Mahabubabad, and Nizamabad.","table":{"headers":["Rank","District","Total Livestock (Lakh)"],"rows":[["1","Rangareddy","14.39"],["2","Nagarkurnool","15.21"],["3","Nalgonda","19.49"],["4","Mahabubabad","11.75"],["5","Nizamabad","12.02"]],"unit":"Lakh numbers, 2019 Census"}},{"a":"Hyderabad","e":"Hyderabad had the lowest total livestock at 0.87 lakh, followed by Medchal-Malkajgiri and Mulugu.","table":{"headers":["Rank","District","Total Livestock (Lakh)"],"rows":[["33","Hyderabad","0.87"],["32","Medchal-Malkajgiri","2.79"],["31","Mulugu","3.65"]],"unit":"Lakh numbers, 2019 Census"}},{"a":"Nalgonda","e":"Nalgonda had the most Fair Price Shops at 1,051, followed by Rangareddy, Sangareddy, Hyderabad, and Khammam.","table":{"headers":["Rank","District","Fair Price Shops"],"rows":[["1","Nalgonda","1,051"],["2","Rangareddy","936"],["3","Sangareddy","855"],["4","Hyderabad","655"],["5","Khammam","748"]],"unit":"Number of shops, Feb 2026"}},{"a":"Mulugu","e":"Mulugu had the fewest shops at 222, followed by Jayashankar and Kumuram Bheem.","table":{"headers":["Rank","District","Fair Price Shops"],"rows":[["33","Mulugu","222"],["32","Jayashankar","277"],["31","Kumuram Bheem","315"]],"unit":"Number of shops, Feb 2026"}},{"a":"Rs. 16,09,902 crore","e":"This grew to Rs. 17,82,198 crore in 2025-26 (PAE), a growth rate of 10.7%.","table":null},{"a":"Rs. 8,89,582 crore","e":"Up from Rs. 8,20,197 crore in 2024-25 (FRE), representing 8.5% growth.","table":null},{"a":"Real Estate, Ownership of Dwelling and Professional Services","e":"This sector contributed 23.4% of GSVA, the largest single contributor, followed by Trade, Repair, Hotels and Restaurants at 20.8%.","table":null},{"a":"Tertiary sector highest","e":"Tertiary sector contributed 67.0% (2024-25) and 68.6% (2025-26) of total GSVA, the largest of the three broad sectors.","table":{"headers":["Sector","2024-25 (FRE) Contribution %","2025-26 (PAE) Contribution %"],"rows":[["Primary","16.6","15.1"],["Secondary","16.5","16.3"],["Tertiary","67.0","68.6"]],"unit":"% Contribution to GSVA at Basic Prices, Current Prices"}},{"a":"Rs. 16,14,771 crore","e":"","table":null},{"a":"Rs. 4,18,931","e":"Up from Rs. 3,80,031 in 2024-25 (FRE).","table":null},{"a":"Rs. 3,57,13,886 crore","e":"Up from Rs. 3,30,68,145 crore in 2024-25 (PE), a growth rate of 8.0%.","table":null},{"a":"Rs. 2,19,575","e":"","table":null},{"a":"Rs. 2,01,89,919 crore","e":"Growth rate of 7.4% over 2024-25 (PE)''s Rs. 1,87,96,955 crore.","table":null},{"a":"Rangareddy","e":"Rangareddy''s GDDP was Rs. 3,41,080 crore, ahead of Hyderabad at Rs. 2,25,860 crore.","table":null},{"a":"Rangareddy","e":"Rangareddy''s per capita income was Rs. 11,29,735, far ahead of Hyderabad (Rs. 4,76,679), the second-highest.",