INSERT INTO chapter_content (chapter_slug, subject_id, chapter_number, title, answers_json) VALUES ('telangana-economy-chapter-3-public-finance', 'telangana-economy-en', 3, 'Public Finance', '[{"a":"December 2023","e":"","table":null},{"a":"Rs. 3,04,865 crore","e":"","table":null},{"a":"Rs. 2,26,982 crore","e":"","table":null},{"a":"Rs. 36,504 crore","e":"","table":null},{"a":"78.9%","e":"","table":null},{"a":"Rs. 3,04,367 crore","e":"","table":null},{"a":"Rs. 2,29,721 crore","e":"","table":null},{"a":"Rs. 74,646 crore","e":"","table":null},{"a":"Total Expenditure grew from Rs. 2,31,825 crore (2023-24) to Rs. 3,04,865 crore (2025-26 BE)","e":"Full breakdown across all budget items (Rs. in crore), excluding Ways & Means Advances.","table":{"headers":["Item","2023-24 Accounts","2024-25 RE","2025-26 BE"],"rows":[["Revenue Receipts","1,69,293","2,02,108","2,29,721"],["Capital Receipts","61,496","64,501","74,646"],["Total Receipts","2,30,790","2,66,609","3,04,367"],["Revenue Expenditure","1,68,514","1,96,219","2,26,982"],["Of which Interest Payments","24,347","17,730","19,369"],["Capital Expenditure","43,918","33,088","36,504"],["Loans and Advances","6,861","19,626","21,351"],["Capital Disbursements","12,533","17,001","20,028"],["Total Expenditure","2,31,825","2,65,935","3,04,865"]],"unit":"Rs. in crore, Source: Telangana Budget at a Glance 2025-26"}},{"a":"State''s Own Tax Revenue is highest at Rs. 1,45,420 crore (63.3%)","e":"Full composition of revenue receipts for 2025-26 (BE).","table":{"headers":["Component","Amount (Rs. crore)","Share (%)"],"rows":[["State''s Own Tax Revenue","1,45,420","63.3"],["Non-Tax Revenue","31,619","13.8"],["Share of Central Taxes","29,900","13.0"],["Grants-in-aid","22,783","9.9"]],"unit":"Rs. in crore, 2025-26 (BE)"}},{"a":"Rs. 41,379 crore","e":"Comprises Loans and Advances (Rs. 21,351 crore) and Capital Disbursements/Public Debt Repayment (Rs. 20,028 crore).","table":null},{"a":"Social services and Economic services","e":"Social services cover Urban Development, Housing, Education, Medical & Public Health, Social Security & Welfare, Nutrition; Economic services cover Agriculture, Rural Development, Energy, Irrigation, Industry, Transport.","table":null},{"a":"Rs. 1,10,967 crore","e":"Up from Rs. 58,610 crore in 2023-24 (Accounts).","table":null},{"a":"Rs. 67,722 crore","e":"Up from Rs. 54,258 crore in 2023-24 (Accounts).","table":null},{"a":"Development expenses: Rs. 1,79,102 crore (78.9%); Non-development expenses: Rs. 47,880 crore (21.1%)","e":"","table":null},{"a":"Rs. 19,369 crore","e":"","table":null},{"a":"Rs. 69,539 crore","e":"Largely through open market borrowings and loans from the Government of India.","table":null},{"a":"Rs. 20,028 crore","e":"","table":null},{"a":"Rs. 2,738 crore","e":"Indicates current revenues are adequate to meet routine expenditure requirements, including interest payments.","table":null},{"a":"Rs. 54,010 crore","e":"Represents the State''s net borrowing requirement after accounting for receipts and expenditure.","table":null},{"a":"SGST, Sales Tax, State Excise, Stamps and Registration Fees, Motor Vehicle Tax","e":"","table":null},{"a":"SGST is highest at 34.9%","e":"Full composition breakdown.","table":{"headers":["Component","Share (%)"],"rows":[["SGST","34.9"],["Sales Tax","27.3"],["State Excise","19.0"],["Stamps and Registration Fees","12.3"],["Motor Vehicle Tax","5.7"]],"unit":"% of SOTR, Q1-Q3 2025-26"}},{"a":"Rs. 86,152 crore to Rs. 92,197 crore","e":"Increase was broad-based across major tax heads.","table":null},{"a":"SGST is the largest component in both years","e":"Full April-December comparison across major tax heads.","table":{"headers":["Component","Apr-Dec 2024-25 (Rs. crore)","Apr-Dec 2025-26 (Rs. crore)"],"rows":[["State Own Tax Revenue (Total)","86,152","92,197"],["SGST","31,508","32,165"],["Sales Tax (VAT)","24,035","25,127"],["State Excise","14,078","17,506"],["Stamps and Registration Fees","10,571","11,304"],["Motor Vehicle Tax","5,303","5,288