INSERT INTO chapter_content (chapter_slug, subject_id, chapter_number, title, answers_json) VALUES ('telangana-economy-chapter-5-industries', 'telangana-economy-en', 5, 'Industries', '[{"a":"Rs. 16,48,613 crore","e":"This represents an overall growth of 10.8% compared to the First Revised Estimates (FRE) for 2024-25.","table":null},{"a":"Rs. 3,04,217 crore","e":"This accounted for 18.5% of the total GSVA, an 8.1% growth compared to Rs. 2,81,411 crore in 2024-25 (FRE).","table":null},{"a":"Rs. 2,81,411 crore","e":"","table":null},{"a":"8.1%","e":"","table":null},{"a":"18.5%","e":"","table":null},{"a":"Manufacturing","e":"Manufacturing contributes 45.1% (Rs. 1,37,229 crore) to the total industrial GSVA.","table":null},{"a":"Manufacturing highest share","e":"","table":{"headers":["Sub-Sector","Share of Industrial GSVA (%)","Value (Rs. crore)","Growth Rate (%)"],"rows":[["Manufacturing","45.1","1,37,229","7.7"],["Construction","30.7","93,404","11.4"],["Electricity, Gas, Water Supply & Utilities","12.4","37,692","10.8"],["Mining and Quarrying","11.8","35,892","-0.6"]],"unit":"Rs. crore and %, 2025-26 (PAE) vs 2024-25 (FRE)"}},{"a":"Construction","e":"Construction exhibited the highest growth rate among all industrial sub-sectors at 11.4%.","table":null},{"a":"Mining and Quarrying","e":"Mining and Quarrying recorded a growth rate of -0.6%.","table":null},{"a":"22.2%","e":"This is based on the October-December 2025 Quarterly Bulletin of the Periodic Labour Force Survey under Current Weekly Status.","table":null},{"a":"17.7% rural, 30.2% urban","e":"","table":null},{"a":"21.9% male, 22.8% female","e":"This shows balanced gender participation with slightly higher female engagement.","table":null},{"a":"24.0%","e":"Rural participation is 20.9% and urban is 31.5% for India.","table":null},{"a":"Male 28.5%, Female 14.2%","e":"This gap is more pronounced than in Telangana, where the gender gap is much smaller.","table":null},{"a":"13,00,567 individuals","e":"","table":null},{"a"