INSERT INTO chapter_content (chapter_slug, subject_id, chapter_number, title, answers_json) VALUES ('telangana-economy-chapter-9-education-and-skill-development', 'telangana-economy-en', 9, 'Education and Skill Development', '[{"a":"$3 trillion","e":"The State''s education reforms aim to build a skilled, productive population capable of supporting this target economy.","table":null},{"a":"SDG 4 (Quality Education)","e":"","table":null},{"a":"James Heckman","e":"A Nobel Laureate whose curve shows early childhood investments yield the highest economic returns.","table":null},{"a":"1,362 sections across 33 districts","e":"","table":null},{"a":"15,490 students","e":"","table":null},{"a":"879 instructors and 596 ayas","e":"","table":null},{"a":"4,000 to 5,000 schools","e":"","table":null},{"a":"31.01.2026","e":"","table":null},{"a":"Government and Local Body Schools have the largest number of institutions; Private Unaided Schools have the largest enrolment share","e":"Full breakdown from Table 10.1, Department of School Education.","table":{"headers":["Management","Schools","Enrolment"],"rows":[["Government and Local Body Schools","24,214","16,61,520"],["Telangana Residential Educational Institutions Society (TREIS)","35","20,982"],["Telangana Model Schools","194","1,08,745"],["Kasturba Gandhi Balika Vidyalayas (KGBV)","495","1,31,644"],["Urban Residential Schools (URS)","29","2,305"],["Other State Government Schools","12","1,254"],["Social Welfare Residential Educational Institutions","235","1,30,485"],["Tribal Welfare Department Institutions","1,679","88,933"],["Tribal Welfare Society Institutions","122","50,148"],["MJPTBCWREIS Schools","294","1,44,729"],["TMREIS Schools","205","73,783"],["Eklavya Model Residential Schools (EMRS)","23","9,676"],["Central Government Schools","7","6,171"],["Private Aided Schools","371","59,894"],["Private Unaided Schools","11,689","37,43,893"],["Madrasas","37","1,838"],["Total","39,641","62,36,000"]],"unit":"Number of schools and students, 2025-26"}},{"a":"Telangana outperforms the national average at every stage","e":"As per UDISE 2024-25 data (Fig 10.1).","table":{"headers":["Stage","Telangana GER","India GER"],"rows":[["Foundational","63.6","41.4"],["Preparatory","110.5","95.4"],["Middle","111.6","90.3"],["Secondary","83.6","68.5"]],"unit":"GER, 2024-25"}},{"a":"Foundational stage","e":"Telangana''s 63.6 GER exceeds the national average of 41.4 by 22.2 points, the largest gap among all stages.","table":null},{"a":"Girls record higher GER than boys at Preparatory, Middle, and Secondary stages","e":"From Fig 10.2, UDISE Report 2024-25.","table":{"headers":["Stage","Boys GER","Girls GER"],"rows":[["Foundational","63.9","63.2"],["Preparatory","109.0","112.2"],["Middle","109.9","113.5"],["Secondary","80.6","86.8"]],"unit":"GER by gender, 2024-25"}},{"a":"21:1 vs 24:1","e":"Telangana''s PTR is better (lower) than the national average during 2024-25.","table":null},{"a":"Rajasthan, Madhya Pradesh, and Kerala","e":"Telangana ranks third with a PTR of 21:1 among Non-Special Category states.","table":null},{"a":"Jharkhand","e":"Jharkhand recorded a PTR of 36, the highest among Non-Special Category states shown in Fig 10.3.","table":null},{"a":"Telangana outperforms India at every level except Foundational, where they are equal","e":"","table":{"headers":["Level","Telangana PTR","India PTR"],"rows":[["Foundational","10:1","10:1"],["Preparatory","11:1","13:1"],["Middle","12:1","17:1"],["Secondary","13:1","21:1"]],"unit":"Pupil-Teacher Ratio, 2024-25"}},{"a":"100%","e":"This was 1.4 percentage points above the national average of 98.6%.","table":null},{"a":"Telangana outperformed the national average at all three transition points","e":"","table":{"headers":["Transition","Telangana","India"],"rows":[["Foundational to Preparatory","100.0%","98.6%"],["Preparatory to Middle","99.9%","92.2%"],["Middle to Secondary","98.9%","86.6%"]],"unit":"Transition rate, 2024-25"}},{"a":"12.3 percentage points","e":"","table":null},{"a":"Girls recorded consistently higher transition rates than boys at every stage","e":"","table":{"headers":["Transition","Boys","Girls"],"rows":[["Foundational to Preparatory","100.0%","100.0%"],["Preparatory to Middle","99.2%","100.0%"],["Middle to Secondary","98.3%","99.6%"]],"unit":"Transition rate by gender, 2024-25"}},{"a":"September 2024","e":"","table":null},{"a":"Rs. 140 crore","e":"","table":null},{"a":"Telangana leads India in Functional Electricity, Digital Library, Playground, and Functional Computer facility, but trails in Girls'' and Boys'' Toilet facilities","e":"","table":{"headers":["Facility","Telangana (%)","India (%)"],"rows":[["Functional Electricity","95.1","91.9"],["Functional Drinking Water","99.5","99.0"],["Functional Girls'' Toilet","91.4","93.3"],["Functional Boys'' Toilet","83.6","90.7"],["Digital Library","85.7","6.9"],["Playground","86.5","83.0"],["Functional Computer Facility","81.2","57.9"]],"unit":"% of schools, UDISE Report 2024-25"}},{"a":"85.7% vs 6.9%","e":"This is highlighted as the State''s key differentiator in learning-enabling infrastructure.","table":null},{"a":"June 2024","e":"","table":null},{"a":"58,632 works amounting to Rs. 706 crore","e":"","table":null},{"a":"Rs. 146 crore","e":"Supported by CSR funding from Singareni Collieries Company Limited (SCCL).","table":null},{"a":"17.9 lakh students across 26,001 schools","e":"","table":null},{"a":"Tuesday, Thursday, and Saturday, at a total cost of Rs. 33.67 crore","e":"","table":null},{"a":"Varies by day, including ragi java on alternate days","e":"","table":{"headers":["Day","Recipes"],"rows":[["Monday","Kichidi, Mixed Vegetable Curry and Egg"],["Tuesday","Rice, Mixed Vegetable Curry, Sambar and Ragi Java"],["Wednesday","Rice, Mixed Vegetable Curry, Green leafy vegetable dhal and Egg"],["Thursday","Vegetable Biryani, Mixed Vegetable Curry and Ragi Java"],["Friday","Rice, Mixed Vegetable Curry, Sambar and Egg"],["Saturday","Rice, Mixed Vegetable Curry, Green leaf