RISP, TGCHE, and BoAT.","table":null},{"a":"2026-27","e":"","table":null},{"a":"1,037 schools","e":"","table":null},{"a":"Every six months","e":"","table":null}]') ON CONFLICT(chapter_slug) DO UPDATE SET subject_id=excluded.subject_id, chapter_number=excluded.chapter_number, title=excluded.title, answers_json=excluded.answers_json;
INSERT INTO chapter_content (chapter_slug, subject_id, chapter_number, title, answers_json) VALUES ('chapter-1-satavahanas', 'telangana-history-te', 1, 'శాతవాహనులు', '[{"a":"ఐతరేయ బ్రాహ్మణం","e":"క్రీస్తుకు పూర్వం వెయ్యి సంవత్సరాల నాటిదిగా పేర్కొనబడింది.","table":null},{"a":"గణతంత్ర రాజ్యాలు","e":"","table":null},{"a":"శ్రీముఖుడు","e":"","table":null},{"a":"క్రీ.పూ. 225","e":"","table":null},{"a":"శాలివాహనులు, శాతకర్ణులు","e":"","table":null},{"a":"450 సంవత్సరాలు","e":"","table":null},{"a":"శ్రీకృష్ణుడు","e":"","table":null},{"a":"నాసిక్","e":"","table":null},{"a":"ఉజ్జయిని","e":"తర్వాత విదిశ నగరాన్ని కూడా ఆక్రమించారు.","table":null},{"a":"ప్రతిష్ఠానపురం","e":"దీనినే పైఠాన్ అని కూడా అంటారు, ఔరంగాబాద్ జిల్లాలో గోదావరి నదికి ఉత్తర తీరాన ఉంది.","table":null},{"a":"అమరావతి","e":"దీన్ని ధాన్యకటకమని కూడా పిలిచేవారు.","table":null},{"a":"శకులు","e":"","table":null},{"a":"సుశర్మ","e":"ఇతన్ని శాతవాహన శ్రీముఖుడు యుద్ధంలో ఓడించి, వధించి మగధరాజ్యాన్ని ఆక్రమించుకున్నాడు.","table":null},{"a":"19 మంది","e":"","table":null},{"a":"300 సంవత్సరాలు","e":"","table":null},{"a":"అరేబియా సముద్రం","e":"","table":null},{"a":"కయిన్స్ ఆఫ్ ఆంధ్ర","e":"ఇందులో భారతీయ క్షత్రియుల రాజ్యాలను గురించి పేర్కొన్నాడు.","table":null},{"a":"ముప్పయి పట్టణాలు","e":"క్రీస్తుకు పూర్వం 300 సంవత్సరాల క్రితం పేర్కొన్నాడు.","table":null},{"a":"కొండాపురం","e":"","table":null},{"a":"గౌతమీపుత్ర పులోమావి","e":"","table":null},{"a":"బుద్ధం, ధర్మం, సంఘం","e":"","table":null},{"a":"హీనయాన బౌద్ధం","e":"","table":null},{"a":"గౌతమీపుత్రుడు","e":"","table":null},{"a":"పులోమావి","e":"","table":null},{"a":"కోటిలింగాల","e":"","table":null},{"a":"డైనేజి పద్ధతి","e":"","table":null},{"a":"విక్రమశకం, శాలివాహనశకం","e":"విక్రమశకం క్రీ.పూ. 58 నుండి, శాలివాహనశకం క్రీ.శ. 76 నుండి లెక్కకు వస్తాయి.","table":null},{"a":"శాలివాహనశకం","e":"","table":null},{"a":"ప్రాకృతం","e":"","table":null},{"a":"పాళీ భాష","e":"","table":null},{"a":"శర్వవర్మ","e":"","table":null},{"a":"కాతంత్ర వ్యాకరణము","e":"","table":null},{"a":"5 సంవత్సరాలు","e":"క్రీ.పూ. 19 నుండి 24 వరకు.","table":null},{"a":"గాధా సప్తశతి","e":"ఇందులో 700 శృంగార గాథలున్నాయి.","table":null},{"a":"కవివత్సలుడు","e":"","table":null},{"a":"అపర బుద్ధుడు","e":"","table":null},{"a":"మహాయాన బౌద్ధం","e":"","table":null},{"a":"శ్రీపర్వతం","e":"కృష్ణా నదీ తీరంలో ఉంది.","table":null},{"a":"బృహత్కథ","e":"","table":null},{"a":"కామసూత్రాలు","e":"","table":null},{"a":"ప్రాజ్ఞ పారమిత సూత్రం, సుహృల్లేఖ","e":"","table":null},{"a":"కందుక క్రీడ","e":"","table":null},{"a":"ఏనుగులు, గుర్రాలు, రథాలు, సైనికులు","e":"","table":null},{"a":"మాతృభక్తి","e":"పేరుకు ముందు తల్లిపేరు చెప్పుకునేవారు.","table":null},{"a":"ధాన్యకటకం, జగ్గయ్యపేట, భట్టిప్రోలు, ఘంటసాల, నాగార్జునకొండ","e":"","table":null},{"a":"బౌద్ధ, వైదిక మతాలు","e":"శాతవాహనుల మతసహనానికి నిదర్శనం.","table":null},{"a":"506 సంవత్సరాలు","e":"క్రీ.పూ. 833 నుండి క్రీ.శ. 327 వరకు అని మూలంలో పేర్కొనబడింది.","table":null}]') ON CONFLICT(chapter_slug) DO UPDATE SET subject_id=excluded.subject_id, chapter_number=excluded.chapter_number, title=excluded.title, answers_json=excluded.answers_json;
INSERT INTO chapter_content (chapter_slug, subject_id, chapter_number, title, answers_json) VALUES ('chapter-10-nizam-chapter-1', 'telangana-history-te', 10, 'నిజాం 1', '[{"a":"ఆసఫ్‌జాహీ నిజాం వంశం","e":"","table":null},{"a":"మీర్ ఖమ్రుద్దీన్‌ఖాన్","e":"","table":null},{"a":"తుర్కీస్తాన్","e":"","table":null},{"a":"షాజహాన్","e":"","table":null},{"a":"చీన్‌ఖులిచ్‌ఖాన్","e":"","table":null},{"a":"షాహబొద్దీన్","e":"","table":null},{"a":"అల్లామీ షహీదుల్లాఖాన్ కుమార్తె","e":"ఇతను షాజహాన్ కాలంలో ప్రధానమంత్రిగా పనిచేశాడు.","table":null},{"a":"1671 ఆగస్టు 11","e":"","table":null},{"a":"బీజాపూర్ గవర్నరు","e":"","table":null},{"a":"పంచ్‌హజారీ","e":"","table":null},{"a":"1707 ఫిబ్రవరి 20","e":"","table":null},{"a":"గజనీ నుండి చట్గాన్ వరకు, కాశ్మీర్ నుండి కర్నాటక వరకు","e":"","table":null},{"a":"ఔరంగజేబు","e":"","table":null},{"a":"వారసత్వ యుద్ధాలు","e":"","table":null},{"a":"ఆజమ్, మొహజమ్‌ల మధ్య","e":"","table":null},{"a":"మొహజమ్ (బహదూర్‌షా)","e":"","table":null},{"a":"ఖాన్‌దౌరాన్, బహదూర్‌ఖాన్","e":"సైద్ (అయోధ్య) ప్రాంతానికి సుబేదారుగాను, లక్నో విభాగానికి ఫౌజ్దారు (సేనాని)గాను నియమించాడు.","table":null},{"a":"ఐదు సంవత్సరాలు, 1712లో","e":"","table":null},{"a":"జహందార్‌షా","e":"","table":null},{"a":"సయ్యద్ సోదరులు (అమీరుల్ ఉమ్రాహసేన్ అలీఖాన్, కుతుబుల్ ముల్క్ అబ్దుల్లాఖాన్)","e":"","table":null},{"a":"దక్షన్","e":"నిజాంకు ఫతేజంగ్, నిజాముల్‌ముల్క్ బిరుదునిచ్చి సత్కరించాడు.","table":null},{"a":"ముబారిజ్‌ఖాన్","e":"","table":null},{"a":"1724 అక్టోబరు 11","e":"ఔరంగాబాద్ సమీపంలోని పెక్కర్‌ఖేడా వద్ద జరిగింది.","table":null},{"a":"1724 అక్టోబరు 11 (ముబారిజ్‌ఖాన్‌ను చంపిన రోజే)","e":"","table":null},{"a":"మహమ్మద్‌షా","e":"దక్షను సుబేదారుగా నియమిస్తున్నట్లు అధికార పత్రం జారీ చేశాడు.","table":null},{"a":"నిజాం ప్రభువుల వంశనామానికి","e":"","table":null},{"a":"విహార భూమి","e":"నాదిర్షా, అహమద్‌షా అబ్దాలీ వంటివారికి ఇది విహారభూమిగా మారింది.","table":null},{"a":"ఢిల్లీ","e":"మహమ్మద్‌షా కబురుపై దక్షనులో స్థిర స్థాపనలో నిమగ్నుడైన నిజాం ఢిల్లీకి బయలుదేరాడు.","table":null},{"a":"ఇరాన్","e":"","table":null},{"a":"మహమ్మద్‌షా అవమానం చేసినందుకు","e":"నాదిర్షాను ఒక అల్పజ్ఞాని కింద తీసుకుని మహమ్మద్‌షా సమాధానాలు పంపలేదు.","table":null},{"a":"2 కోట్ల రూపాయలు","e":"","table":null},{"a":"నాదిర్షాను చంపివేశారనే పుకార్లు","e":"ఈ ఊచకోతలో లక్షాయాభైవేలమంది చనిపోయారు.","table":null},{"a":"నెమలి సింహాసనం","e":"15, 20 కోట్ల విలువైన ధనరాసులు, వజ్ర వైడూర్యాలతో పాటు నెమలి సింహాసనాన్ని సమర్పించారు.","table":null},{"a":"1774","e":"","table":null},{"a":"తిరుచనాపల్లి","e":"మద్రాసు పరిపరచుకున్నాడు, ఆనాడు ఔరంగాబాద్ దక్షన్ రాజధాని.","table":null},{"a":"బాలకొండ","e":"తెలంగాణాలోని బాలకొండ పాలకుడు స్వాతంత్ర్యం ప్రకటించుకోవడంతో జయించాడు.","table":null},{"a":"ఫ్రెంచివారు, బ్రిటీష్‌వారు","e":"","table":null},{"a":"దక్షన్‌లో నిజాం ఆస్థానంలో","e":"","table":null},{"a":"ఢిల్లీ సింహాసనం","e":"","table":null},{"a":"బురహాన్‌పూర్ వద్ద, 1748లో","e":"","table":null},{"a":"ఖుల్దాబాద్ సమీపంలోని ఫకీరు","e":"","table":null},{"a":"ఏడు కుల్చాలు, ఐదు తిన్నాడు","e":"దీని ఆధారంగా ఫకీరు నిజాం వంశం ఐదు తరాలు అంతరించిపోతుందని జోస్యం చెప్పాడు.","table":null},{"a":"ఆశీర్వదించి పంపించాడు","e":"ఆనాటి పసుపు పచ్చబట్ట మధ్య గుండ్రటి రొట్టెముక్క నిజాం ప్రభుత్వ పతాకమైంది.","table":null},{"a":"శ్వేతవర్ణంలో","e":"","table":null}]') ON CONFLICT(chapter_slug) DO UPDATE SET subject_id=excluded.subject_id, chapter_number=excluded.chapter_number, title=excluded.title, answers_json=excluded.answers_json;
INSERT INTO chapter_content (chapter_slug, subject_id, chapter_number, title, answers_json) VALUES ('chapter-11-nizam-chapter-2', 'telangana-history-te', 11, 'నిజాం- 2', '[{"a":"1761","e":"","table":null},{"a":"సదాశివరావు పీష్వా","e":"","table":null},{"a":"అహమద్‌షా అబ్దాలీ","e":"ఇతను ఇరాన్ దేశపువాడు.","table":null},{"a":"మల్హర్‌రావు హోల్కర్","e":"","table":null},{"a":"ఒకే దెబ్బతో శత్రువులను నాశనం చేయటం ప్రయోజనకారి అని భావించడం","e":"","table":null},{"a":"చిన్న సహాయం చేసి ఊరుకున్నాడు","e":"దీనితో అతి శ్రేష్ఠమైన హిందూ సైన్యం పూర్తిగా ఓడిపోయి సర్వనాశనం అయిపోయింది.","table":null},{"a":"దురాక్రమణదారుడు (అహమద్‌షా అబ్దాలీ)","e":"","table":null},{"a":"హైదర్ అలీ","e":"","table":null},{"a":"గుంటూరు మండలం","e":"","table":null},{"a":"1782","e":"","table":null},{"a":"జాన్సన్","e":"","table":null},{"a":"గుంటూరు మండలం","e":"","table":null},{"a":"1778","e":"","table":null},{"a":"మీర్ ఆలమ్","e":"","table":null},{"a":"టిప్పుసుల్తాన్","e":"ఈ యుద్ధంలో కర్నూలు నవాబు నిజాంకు ఎదురు తిరిగాడు.","table":null},{"a":"సర్దేశ్‌ముఖీ, చౌత్","e":"","table":null},{"a":"మోషేరేమాండ్","e":"ఇతను ఫ్రెంచ్ సేనాని.","table":null},{"a":"బేగమ్‌ల మాటలు విని మధ్యలోనే యుద్ధం ఆపివేయడం","e":"","table":null},{"a":"36 లక్షల ఆదాయంవచ్చే ఇలాకాను, 2 లక్షల రూపాయల నగదును","e":"సతారా, బీదరు, బీజాపూర్, దౌలతాబాద్ మొదలైన ఇలాకాలు, తన ప్రధాని అరస్తూజాను కూడా సమర్పించుకున్నాడు.","table":null},{"a":"హైదరాబాద్","e":"","table":null},{"a":"ఫ్రెంచ్ సేనలు","e":"","table":null},{"a":"అలీజా","e":"","table":null},{"a":"టిప్పుసుల్తాన్","e":"","table":null},{"a":"1798లో లార్డ్ వెల్లస్లీ","e":"ఇతను గవర్నరు జనరల్‌గా వచ్చాడు.","table":null},{"a":"నిజాం","e":"","table":null},{"a":"మీర్ ఆలమ్","e":"","table":null},{"a":"టిప్పుసుల్తాన్","e":"","table":null},{"a":"సీడెడ్ జిల్లాలు","e":"","table":null},{"a":"1803","e":"43 సంవత్సరాల సుదీర్ఘ పరిపాలన జరిపాడు.","table":null},{"a":"40 వేల రూపాయలు","e":"సాలీన కైంకర్యాలకు మంజూరు చేశాడు.","table":null},{"a":"The treaty of subsidiary","e":"","table":null},{"a":"సికిందరాబాద్","e":"","table":null},{"a":"భవన నిర్మాణ పథకం","e":"","table":null},{"a":"\"నీకు ఎంత భవనం కావాలో అంతే పథకం తయారు చేసుకోవచ్చు\" అని","e":"","table":null},{"a":"కోడి గుడ్డంతనో, పోస్టుకార్డంతనో పథకం తయారు చేసుకొమ్మని","e":"","table":null}]') ON CONFLICT(chapter_slug) DO UPDATE SET subject_id=excluded.subject_id, chapter_number=excluded.chapter_number, title=excluded.title, answers_json=excluded.answers_json;
INSERT INTO chapter_content (chapter_slug, subject_id, chapter_number, title, answers_json) VALUES ('chapter-12-nizam-chapter-3', 'telangana-history-te', 12, 'నిజాం- 3', '[{"a":"మీర్ మహబూబ్ అలీఖాన్ బహదూర్","e":"","table":null},{"a":"రెండు సంవత్సరాల వయస్సులో, 1869లో","e":"","table":null},{"a":"సాలార్‌జంగ్","e":"","table":null},{"a":"షమ్‌ఘుల్ ఉమ్రాను","e":"","table":null},{"a":"బ్రిటీష్ వారికి బాకీ ఉన్న 8 మిలియన్ పౌండ్ల డబ్బును సమకూర్చిపెట్టుకున్నాడు","e":"","table":null},{"a":"1883","e":"","table":null},{"a":"18 ఏళ్ళు","e":"","table":null},{"a":"లార్డ్ రిప్పన్","e":"చౌమహల్లా రాజ ప్రాసాదంలో దర్బారు జరిగింది, ఈ సమావేశంలోనే నిజాంకు సమస్త అధికారాలు దత్తమైనాయి.","table":null},{"a":"ముల్కీ-నాన్ ముల్కీ సమస్యలు","e":"","table":null},{"a":"జాయింట్ అడ్మినిస్ట్రేటర్‌గా","e":"","table":null},{"a":"ఉర్దూ భాష","e":"","table":null},{"a":"1887 ఏప్రిల్‌లో","e":"","table":null},{"a":"అస్మాన్‌జా, సర్ వికారుల్ ఉమ్రా, మహారాజా సర్ కిషన్ ప్రసాద్","e":"","table":{"headers":["ప్రధాని పేరు","పదవీకాలం"],"rows":[["అస్మాన్‌జా","1893 వరకు"],["సర్ వికారుల్ ఉమ్రా","1901 వరకు"],["మహారాజా సర్ కిషన్ ప్రసాద్","1912 వరకు (11 సంవత్సరాలు)"]],"unit":"ప్రధాని పదవీకాలం"}},{"a":"''ఖానూన్-చె-ముబారక్''","e":"అందులో మంత్రివర్గం, విధాన సభ మొదలైనవి చేర్చబడ్డాయి, కానీ ప్రజలకు రాజ్యాంగపరమైన హక్కులేవీ లభించలేదు.","table":null},{"a":"అఫ్గన్ యుద్ధాలు","e":"నిజాం 60 లక్షల రూపాయల నగదు, పెద్ద సంఖ్యలో సైన్యం పంపి బ్రిటీష్ వారిని ఆదుకున్నాడు.","table":null},{"a":"బిరారు","e":"నిజాంకు జి.సి.బి. (నైట్ ఆఫ్ గ్రాండ్ క్రాస్) బిరుదు ప్రదానం చేశారు.","table":null},{"a":"\"గేవ్ కర్జన్ బిరార్\" (జి-అనగా గేవ్, సి-అనగా కర్జన్, బి-అనగా బిరారు)","e":"","table":null},{"a":"శ్రీపాద దామోదర్ సాత్వాలేకర్, ఆర్యసమాజ్ నాయకుడు కేశవరావుతో","e":"","table":null},{"a":"లెక్చర్లివ్వడం మానుకో, పాటకచ్చేరీలు జరుపు, చిత్రలేఖనంతో డబ్బు సంపాదించుకో అన్న షరతును అంగీకరించనందుకు","e":"","table":null},{"a":"సంస్థానం నుంచి","e":"","table":null},{"a":"తుఫాను, భారీ వర్షాలవల్ల మూసీనది వరదలు","e":"","table":null},{"a":"19000 ఇళ్ళు, దాదాపు 15000 మంది","e":"మూడు కోట్ల రూపాయలు నష్టం వాటిల్లినట్లు అంచనావేశారు.","table":null},{"a":"సర్ మోక్షగుండం విశ్వేశ్వరయ్య","e":"హైదరాబాద్ నగరానికి వరద, మురుగు నీటి నుంచి శాశ్వతంగా రక్షణ కల్పించే పథకం రూపొందించే బాధ్యత అప్పగించారు.","table":null},{"a":"ధర్మాత్ముడు","e":"హిందూ-ముస్లిం భేదభావం లేకుండా పాలన సాగించాడు.","table":null},{"a":"మాణిక్య ప్రభువు","e":"అందుకే ఆయన పేరు వచ్చేవిధంగా తమ పిల్లల పేర్లు పెట్టుకున్నారు (మహబూబ్‌రాయ్, మహబూబ్ కరన్, మహబూబ్ పర్షాద్, మహబూబ్ రెడ్డి).","table":null},{"a":"అఘోరనాథ్ చట్టోపాధ్యాయ","e":"","table":null},{"a":"అఘోరనాథ్","e":"","table":null},{"a":"హైదరాబాద్ నుండి బహిష్కరణ శిక్ష","e":"1888లో వైస్రాయ్‌కు అపీలు చేసుకోగా రెసిడెంటును బయటికి పంపివేసి తిరిగి ఉద్యోగంలో తీసుకున్నారు.","table":null},{"a":"అఘోరనాథుడు","e":"","table":null},{"a":"1911 ఏప్రిల్ 3, ఫలక్‌నుమా రాజభవనంలో","e":"","table":null}]') ON CONFLICT(chapter_slug) DO UPDATE SET subject_id=excluded.subject_id, chapter_number=excluded.chapter_number, title=excluded.title, answers_json=excluded.answers_json;
INSERT INTO chapter_content (chapter_slug, subject_id, chapter_number, title, answers_json) VALUES ('chapter-13-nizam-chapter-4', 'telangana-history-te', 13, 'నిజాం- 4', '[{"a":"1911 ఆగస్టు 11","e":"","table":null},{"a":"1911 ఆగస్టు 11 (అదేరోజు)","e":"తన 21వ యేట గద్దెనెక్కాడు.","table":null},{"a":"కలకత్తా నుండి ఢిల్లీకి","e":"","table":null},{"a":"లక్నో, 1916 డిసెంబరు","e":"","table":null},{"a":"అంబికా చరణ్ మజుందార్","e":"","table":null},{"a":"మహారాజా సర్‌కిషన్ ప్రసాద్","e":"","table":null},{"a":"నిన్ను నా నాన్నగారిని చూసావు కదా, మాలో నీకు ఏ భేదం కనిపించింది","e":"దీనికి సరోజినీ నాయుడు దేవుడు దివంగతరాజుకు ''దిల్'' (ఔదార్యం) ఇచ్చాడని, నిజాంకు ''దిమాగ్'' (బుద్ధి) ఇచ్చాడని బదులిచ్చింది.","table":null},{"a":"1914","e":"","table":null},{"a":"మంత్రివర్గాన్ని తొలగించి పరిపాలనా బాధ్యతలను తానే స్వీకరించాడు","e":"","table":null},{"a":"నజరానా","e":"","table":null},{"a":"కానుక","e":"ప్రభువుల కానుకలంటే ఈనాటి పరిభాషలో లంచం.","table":null},{"a":"అపరిమితంగా ధన సహాయం","e":"","table":null},{"a":"హిజ్ ఎగ్జాల్టెడ్ హైనెస్","e":"25 తుపాకీగుళ్ళ సైనిక వందనంతో సత్కరించారు.","table":null},{"a":"నిజాం నవాబు ఒక్కడే","e":"","table":null},{"a":"సర్ అలీ ఇమామ్","e":"","table":null},{"a":"ఉత్తరాది","e":"పేరుమోసిన ప్లీడరు.","table":null},{"a":"న్యాయశాఖ మంత్రిగా","e":"","table":null},{"a":"నజరానా పద్ధతి","e":"","table":null},{"a":"రాయ్‌బాల్ ముకుంద్","e":"","table":null},{"a":"మలబార్‌లోని మాప్లా జాతివారిని","e":"","table":null},{"a":"ఖిలాఫత్ ఉద్యమం","e":"","table":null},{"a":"పదిహేను వేల రూపాయలు","e":"","table":null},{"a":"1922 సెప్టెంబరు 5","e":"","table":null},{"a":"ఫరీదున్ ముల్క్, వలీ ఉద్దౌలా","e":"ఒక్కొక్క సంవత్సరం చొప్పున ప్రధానులుగా పనిచేశారు.","table":null},{"a":"మహారాజా సర్ కిషన్ ప్రసాద్ బహదూర్","e":"బ్రిటీష్‌వారు జోక్యం చేసుకొని నియమించారు, ఇతడు ఐదేళ్ళు ఆ పదవిలో కొనసాగాడు.","table":null},{"a":"మహారాజా బహదూర్ ప్రధానిగా, రాజాబహదూర్ వెంక్ట్రామారెడ్డి కోత్వాల్‌గా","e":"","table":null},{"a":"సర్ అక్బర్ హైదరీ","e":"ఇతడు 1941 వరకు ప్రధానిగా ఉన్నాడు.","table":null},{"a":"స్వాతంత్ర్యం ఇవ్వలేదు","e":"కొన్ని ప్రజాభ్యుదయకరమైన పనులు మాత్రం చేశాడు.","table":null},{"a":"1400 ఎకరాలు","e":"","table":null},{"a":"ఉర్దూలో","e":"","table":null},{"a":"దారుల్ తర్జుమా (అనువాద విభాగం)","e":"","table":null},{"a":"ఉస్మాన్‌సాగర్, హిమాయత్ సాగర్‌లు","e":"","table":null},{"a":"మూడు లక్షల ఎకరాలు","e":"","table":null},{"a":"పాలేరు, వైరా, తుంగభద్ర, రాజోలిబండ, కడెం, మూసీ, మానేరు","e":"","table":null},{"a":"నవాబు అలీ నవాజ్ జంగ్","e":"","table":null},{"a":"ఆసియా ఖండంలో","e":"","table":null},{"a":"ఉస్మానియా విశ్వవిద్యాలయం, ఉస్మానియా దవాఖానా, హైకోర్టు, స్టేటు సెంట్రల్ లైబ్రరీ, అసెంబ్లీ భవనాలు","e":"","table":null},{"a":"మొగలు చక్రవర్తులకు","e":"","table":null},{"a":"నిజాం గ్యారెంటీడ్ కంపెనీ","e":"","table":null},{"a":"1930","e":"","table":null},{"a":"పదికోట్ల రూపాయలు","e":"","table":null},{"a":"నిజాం స్టేట్ రైల్వే (ఎస్.ఎస్.ఆర్.)","e":"","table":null},{"a":"1932","e":"","table":null},{"a":"హైదరాబాద్ (నిజాం రాష్ట్రం)","e":"","table":null},{"a":"60 శాతం","e":"","table":null},{"a":"40 శాతం","e":"","table":null},{"a":"82,698 చదరపు మైళ్ళు","e":"","table":null},{"a":"8,100 చదరపు మైళ్ళు","e":"","table":null},{"a":"3,262 చదరపు మైళ్ళు","e":"","table":null},{"a":"1,100 చదరపు మైళ్ళు, 59.21 శాతం","e":"","table":null},{"a":"50 లక్షల ఎకరాలు","e":"","table":null},{"a":"3 కోట్లు","e":"","table":null},{"a":"పన్ను చెల్లించేవాడు కాదు","e":"పైగా నవాబుకు ప్రభుత్వ ఖజానా నుంచి ఏటా యాభై లక్షలు చెల్లించవలసి వచ్చేది.","table":null},{"a":"30 లక్షలు","e":"","table":null},{"a":"20 లక్షలు","e":"","table":null},{"a":"15 లక్షలు","e":"","table":null},{"a":"రైత్వారీ పద్ధతి","e":"","table":null},{"a":"దేశ్‌ముఖ్, దేశపాండ్యా, ముఖ్తేదారు, బంజర్‌దార్, ఇజారాదార్","e":"","table":null},{"a":"రకరకాల బిరుదులతో","e":"","table":null},{"a":"రుస్తుంకు దీటైనవాడని","e":"","table":null},{"a":"ముజఫర్ ఉల్-ముల్క్","e":"","table":null},{"a":"''ఆలాహజ్రత్''గానే","e":"","table":null},{"a":"14 సంస్థానాలు","e":"","table":null},{"a":"120 గ్రామాలు, 97 శివారు గ్రామాలు","e":"","table":null},{"a":"విరాళపు పన్ను","e":"","table":null},{"a":"నుజుల్ (ఇండ్లపన్ను)","e":"","table":null},{"a":"సీసు బంచరాయి","e":"","table":null},{"a":"1340వ ఫస్లీ","e":"","table":null},{"a":"ఆయాగాళ్ళు","e":"","table":null},{"a":"ఏనుగు పన్ను","e":"","table":null},{"a":"ఎలాంటి ఆశలు పెట్టుకోవద్దని","e":"","table":null},{"a":"సంధి","e":"","table":null},{"a":"''నిజాం ఆఫ్ హైదరాబాద్ అండ్ బీరారు''","e":"","table":null},{"a":"నిజాం పతాకం","e":"","table":null},{"a":"ప్రిన్స్ ఆఫ్ బీరారు","e":"","table":null},{"a":"25 లక్షల రూపాయలు","e":"","table":null},{"a":"సనదులు, గౌరవాలు","e":"నిజాం కొత్తగా ఏమీ పొందిందేమీ లేదు, సనదులు గౌరవాలు మాత్రమే తప్ప.","table":null}]') ON CONFLICT(chapter_slug) DO UPDATE SET subject_id=excluded.subject_id, chapter_number=excluded.chapter_number, title=excluded.title, answers_json=excluded.answers_json;
