":"దివానీ, ఫౌజ్దారీ కేసులు","e":"","table":null},{"a":"వైద్యం, మింటు (టంకసాల), ముద్రణశాల, పి.డబ్ల్యూ.డి.","e":"","table":null},{"a":"క్యాబినెట్ పద్ధతి","e":"","table":null},{"a":"ఒక మదరుల్-మొహాం (ప్రధానమంత్రి), నలుగురు మోహిసుల్-మొహాంలు (మంత్రులు)","e":"","table":null},{"a":"1874","e":"","table":null},{"a":"ఎగుమతి, దిగుమతులపై","e":"","table":null},{"a":"సాలార్‌జంగ్","e":"","table":null},{"a":"తాటి, మొహవ్వ (ఇప్ప), భంగ్, గాంజా","e":"","table":null},{"a":"స్టాంపు డ్యూటీ","e":"","table":null},{"a":"హాలీ సిక్కా","e":"","table":null},{"a":"10 శాతం","e":"","table":null},{"a":"''క్యూరిస్ ప్రాఫిట్''","e":"","table":null},{"a":"పేష్కషులు, లోకల్‌ఫండ్ సెస్సులు, స్టాంపు డ్యూటీలు, రుసుములు","e":"","table":null},{"a":"రుణభారం నుండి విముక్తి","e":"","table":null},{"a":"గతంలో అభ్యుదయ పనులు చేసిన ప్రధానులెదుర్కొన్న కప్టాలే","e":"","table":null},{"a":"''ప్రవేశపెట్టు''","e":"","table":null},{"a":"1883","e":"","table":null},{"a":"ప్రధానుల పాత్ర","e":"","table":null},{"a":"ఎనిమిదవ భాగం","e":"","table":null},{"a":"22 లక్షలు","e":"","table":null},{"a":"6 లక్షలు","e":"","table":null},{"a":"16వ భాగం","e":"","table":null},{"a":"ఫ్రెయిజర్","e":"","table":null},{"a":"14 వేలకు","e":"","table":null},{"a":"హిందువులు 4919, ముస్లింలు 2882","e":"","table":null},{"a":"హిందువులు 479, ముస్లింలు 1435","e":"","table":null},{"a":"హిందువులు 2306, ముస్లింలు 347","e":"","table":null},{"a":"హిందువులు 37, ముస్లింలు 164","e":"","table":null},{"a":"హిందువులు 234, ముస్లింలు 378","e":"","table":null},{"a":"హిందువులు 1300, ముస్లింలు 58","e":"","table":null},{"a":"హిందువులు 2, ముస్లింలు 0","e":"ఈ శాఖలో ముస్లింలు లేరు.","table":null}]') ON CONFLICT(chapter_slug) DO UPDATE SET subject_id=excluded.subject_id, chapter_number=excluded.chapter_number, title=excluded.title, answers_json=excluded.answers_json;
INSERT INTO chapter_content (chapter_slug, subject_id, chapter_number, title, answers_json) VALUES ('chapter-15-modati-swatantra-samaram', 'telangana-history-te', 15, 'మొదటి స్వతంత్ర సమరం', '[{"a":"1857","e":"","table":null},{"a":"నాలుగు మాసాలకే","e":"","table":null},{"a":"1849 జనవరి 12","e":"","table":null},{"a":"స్వతంత్ర రాజ్యాలు, ఆధార రాజ్యాలు, అధీన రాజ్యాలు","e":"","table":null},{"a":"మూడు కొత్త విధానాలు","e":"","table":null},{"a":"బర్మా, సిక్కిం, పంజాబు","e":"","table":null},{"a":"కాంటిజెంట్ సైన్యం","e":"","table":null},{"a":"అంతం చేశాడు","e":"","table":null},{"a":"కర్నాటక, తంజావూరు రాజులు","e":"","table":null},{"a":"పింఛనుదారుడయ్యాడు","e":"","table":null},{"a":"1856 మార్చి 5","e":"","table":null},{"a":"1866 డిసెంబరు 19","e":"","table":null},{"a":"వారసీన్ పద్ధతి, జాన్‌షీన్ పద్ధతి","e":"","table":null},{"a":"వారి కొడుకులకో, సమీప రక్త సంబంధీకులకో","e":"","table":null},{"a":"దత్తు తీసుకున్న వారికి","e":"","table":null},{"a":"జాన్‌షీన్ పద్ధతి","e":"","table":null},{"a":"నిర్వారసత్వ సిద్ధాంతం (Doctrine of Lapse)","e":"","table":null},{"a":"1858","e":"","table":null},{"a":"ఝాన్సీలక్ష్మీబాయి","e":"","table":null},{"a":"తిరస్కరించాడు","e":"","table":null},{"a":"కర్నాటక నవాబు మహమ్మద్‌గౌర్","e":"","table":null},{"a":"8 లక్షల రూపాయలు","e":"","table":null},{"a":"నానాసాహెబ్‌కు","e":"","table":null},{"a":"తంజావూరు రాజు","e":"","table":null},{"a":"తంజావూరు","e":"","table":null},{"a":"క్రిస్సన్ అనే రష్యా చరిత్రకారుడు","e":"","table":null},{"a":"ఎక్కువ సమయం","e":"","table":null},{"a":"తంతి ద్వారా","e":"","table":null},{"a":"రెసిడెంటు","e":"","table":null},{"a":"సాలార్‌జంగ్","e":"","table":null},{"a":"బెదిరింపు లేఖలు","e":"","table":null},{"a":"రోహిలా దళానికి","e":"","table":null},{"a":"ఒకటవ, మూడవ అశ్వికదళాలు","e":"","table":null},{"a":"వెయ్యి రూపాయలు","e":"","table":null},{"a":"చీదాఖాన్","e":"","table":null},{"a":"3 వేల రూపాయలు","e":"","table":null},{"a":"రెసిడెంటుకు","e":"","table":null},{"a":"మక్కామసీదులో","e":"","table":null},{"a":"తుర్రేబాజ్‌ఖాన్","e":"","table":null},{"a":"1857 జూలై 17, 500 మంది","e":"","table":null},{"a":"32 మంది","e":"","table":null},{"a":"షాద్‌నగర్","e":"మొగుల్ గిద్ద అనే గ్రామంలో పట్టుకున్నారు.","table":null},{"a":"అల్లాఉద్దీన్","e":"","table":null},{"a":"ద్వీపాంతరవాస శిక్ష","e":"","table":null},{"a":"1884","e":"","table":null},{"a":"కాల్చి వేశారు","e":"తప్పించుకునే ప్రయత్నం చేస్తుండగా సాలార్‌జంగ్ సైనికులు కాల్చివేశారు.","table":null},{"a":"గొలుసులతో బిగించి నగ్నరూపంలో రెసిడెన్సీ ప్రధాన ద్వారానికి వేలాడతీశారు","e":"","table":null},{"a":"''స్టార్ ఆఫ్ ఇండియా''","e":"","table":null},{"a":"విక్టోరియా మహారాణి","e":"","table":null},{"a":"ప్రత్యేక దర్బారులో","e":"","table":null},{"a":"రెసిడెంటుపై","e":"","table":null},{"a":"పక్కనే ఉన్న నిజాం అధికారికి","e":"","table":null},{"a":"షోలాపూర్ సంస్థానాధీశుడు","e":"","table":null},{"a":"నిజాంకు","e":"","table":null},{"a":"50 లక్షలు","e":"","table":null},{"a":"షమ్స్‌ఘుల్ ఉమ్రా","e":"","table":null},{"a":"సర్ వికారుల్ ఉమ్రా","e":"","table":null},{"a":"బంధించి మద్రాసుకు పంపిస్తామని","e":"","table":null},{"a":"మేజోళ్ళు విడిచి దారటోపి తీసి వంగి వంగి సలాములు చేసేవారు","e":"","table":null},{"a":"''నియాజ్‌మంద్'' (వినయ విధేయుడు), ''మాబదౌలత్'' (దేవరవారు)","e":"","table":null}]') ON CONFLICT(chapter_slug) DO UPDATE SET subject_id=excluded.subject_id, chapter_number=excluded.chapter_number, title=excluded.title, answers_json=excluded.answers_json;
INSERT INTO chapter_content (chapter_slug, subject_id, chapter_number, title, answers_json) VALUES ('chapter-16-paripalana-vyavastha', 'telangana-history-te', 16, 'పరిపాలనా వ్యవస్థ', '[{"a":"బాబ్-ఎ-హుకుమత్","e":"","table":null},{"a":"సదరె-ఎ-ఆజమ్ (ప్రధానమంత్రి)","e":"","table":null},{"a":"9కి","e":"","table":null},{"a":"5 వేల వేతనం, నూరు రూపాయల అలవెన్స్","e":"","table":null},{"a":"4 వేల రూపాయలు","e":"","table":null},{"a":"దేశంలోని నలుమూలల నుంచి మతానుబంధంతో నిమిత్తంలేకుండా నిపుణులైనవారిని రప్పించి తన పరిపాలన చక్రంలో ఇమిడ్చేవాడు","e":"","table":null},{"a":"సర్ ఎం. విశ్వేశ్వరయ్య","e":"","table":null},{"a":"చక్కని పరిపాలనా యంత్రాంగాన్ని","e":"","table":null},{"a":"''జాబితె-ఎ-అక్లాక్'' (సివిల్ కోడ్)","e":"","table":null},{"a":"1340 హిజ్రి, 16 జమాదుల్ అవ్వల్","e":"","table":null},{"a":"టీ తాగడం, సిగరెట్ పీల్చడం","e":"","table":null},{"a":"దస్తార్ పెట్టుకొని, షేర్వాణీ ధరించి","e":"","table":null},{"a":"1334 హిజ్రి, 17 షవ్యాల్","e":"","table":null},{"a":"పాలమూరు","e":"","table":null},{"a":"మహబూబాబాద్","e":"","table":null},{"a":"పోచంచర్ల","e":"","table":null},{"a":"బమ్మెరపోతన రచించిన శ్రీమదాంధ్ర భాగతములోని కొంతభాగాన్ని రచించిన యలగందల నారయ ఈ గ్రామవాసి అని ఒక అభిప్రాయముంది","e":"","table":null},{"a":"నిజామాబాద్","e":"","table":null},{"a":"జనగామ","e":"","table":null},{"a":"''జిల్లా జనగామ''","e":"","table":null},{"a":"''పాడు''","e":"","table":null},{"a":"పల్లె","e":"","table":null},{"a":"పహాడ్‌గా","e":"","table":null},{"a":"బూర్గంపహాడ్","e":"","table":null},{"a":"కొండ","e":"","table":null},{"a":"ఆంధ్ర సంస్కృతిని","e":"","table":null},{"a":"ఉస్మాన్‌సాగర్, హిమాయత్ సాగర్","e":"","table":null},{"a":"ఒక పథకాన్ని","e":"","table":null},{"a":"బృహత్తరమైన భూగర్భ మురుగు నీటి పారుదల పథకాన్ని","e":"","table":null},{"a":"హైదరాబాద్ సంస్థానాలకు మాత్రమే","e":"","table":null},{"a":"83 రూపాయల 5 అణాల 3 పైసలు","e":"","table":null},{"a":"1883 వరకు","e":"","table":null},{"a":"1894లో","e":"","table":null},{"a":"172.5 గ్రెయిన్లు","e":"","table":null},{"a":"ఉస్మానియా సిక్కా (నాణెం)","e":"","table":null},{"a":"''జర్బ్ ఫర్ఖుందా బున్యద్ హైదరాబాద్ జులూస్ మైమనత్ మనూసే''","e":"","table":null},{"a":"చార్మినార్ బొమ్మ","e":"","table":null},{"a":"హాలీ సిక్కా","e":"","table":null},{"a":"''అయిన్'' (ఐ) అనే అక్షరం","e":"","table":null},{"a":"ఉర్దూ లిపిలో","e":"","table":null},{"a":"ఇంగ్లీషులో","e":"","table":null},{"a":"నాసిక్‌లోని సెక్యూరిటీ ప్రింటింగ్ ప్రెస్","e":"","table":null},{"a":"అయిదు, పదిరూపాయల నోట్లు","e":"","table":null},{"a":"నూరు రూపాయల నోటు, రెండువేల రూపాయల నోటు","e":"","table":null},{"a":"రూపాయి నోటు","e":"","table":null},{"a":"1955 ఏప్రిల్ 1","e":"","table":null},{"a":"ప్రధాన న్యాయమూర్తి, జుడిషియల్ కమిటీ సభ్యులు, అసెంబ్లీ చైర్మన్","e":"","table":null},{"a":"అకౌంటెంట్ జనరల్, ఐ.జి.పి, వైస్‌చాన్సలర్, పబ్లిక్ సర్వీస్ కమీషన్ సభ్యులు, హైకోర్టు న్యాయమూర్తులు, సెక్రటరీ కో ఆర్డినేషన్","e":"","table":null},{"a":"కార్యదర్శి, సూబేదార్లు, చీఫ్ ఇంజనీర్, ఎక్సైజ్ సూపరింటెండెంట్, కన్జర్వేటర్ ఆఫ్ ఫారెస్ట్స్, ఆదాయపు పన్ను, విద్య, వైద్య శాఖల డైరెక్టర్లు","e":"","table":null},{"a":"జాయింట్ సెక్రటరీ, సెక్రటరీలు, డైరెక్టర్లు","e":"","table":null},{"a":"జైరంగాబాద్ మిల్స్ లిమిటెడ్, ఉస్మాన్ షాహీ మిల్స్ లిమిటెడ్, ఆజంజాహీ మిల్స్ లిమిటెడ్, మహబూబ్ షాహీ మిల్స్ లిమిటెడ్, రాంగోపాల్ మిల్స్ లిమిటెడ్, హైదరాబాద్ స్పిన్నింగ్ అండ్ వీవింగ్ మిల్స్","e":"","table":null},{"a":"52 వేలమంది","e":"","table":null},{"a":"సింగరేణి గనులలో","e":"","table":null},{"a":"వెయ్యి ఔన్సుల బంగారం","e":"","table":null},{"a":"సున్నపురాయి, గ్రానేటు, అభ్రకము, ఇనుము, క్వార్ట్జ్","e":"","table":null},{"a":"దక్షను గ్లాస్ ఫ్యాక్టరీ","e":"","table":null},{"a":"వజీర్ సుల్తాన్ అండ్‌కో సిగరెట్టు ఫ్యాక్టరీ","e":"","table":null}]') ON CONFLICT(chapter_slug) DO UPDATE SET subject_id=excluded.subject_id, chapter_number=excluded.chapter_number, title=excluded.title, answers_json=excluded.answers_json;
INSERT INTO chapter_content (chapter_slug, subject_id, chapter_number, title, answers_json) VALUES ('chapter-17-andhra-janasangham-mahasabhalu', 'telangana-history-te', 17, 'ఆంధ్ర జనసంఘం & మహాసభలు', '[{"a":"1921 నవంబరు 12","e":"","table":null},{"a":"హైదరాబాద్‌లోని వివేకవర్ధనీ థియేటర్","e":"","table":null},{"a":"హిందూ సంస్కార సభ","e":"","table":null},{"a":"ధోండే కేశవ కార్వే మహాశయుడు","e":"","table":null},{"a":"పూణె మహిళా విశ్వవిద్యాలయ సంస్థాపకుడు","e":"","table":null},{"a":"మాడపాటి హనుమంతరావు, ఆలంపల్లి వెంకటరామారావు","e":"","table":null},{"a":"హైకోర్టు న్యాయవాదులు","e":"","table":null},{"a":"తెలుగులో","e":"","table":null},{"a":"విసుక్కున్నారు, వినలేదు","e":"","table":null},{"a":"ఆలంపల్లి వెంకటరామారావు","e":"","table":null},{"a":"నిరసన చప్పట్లు కొట్టారు, గోల చేశారు","e":"","table":null},{"a":"టేకుమాల రంగారావు గారింట్లో","e":"","table":null},{"a":"ఒక సంఘం","e":"","table":null},{"a":"నిజాంరాష్ట్ర ఆంధ్రజన కేంద్ర సంఘం","e":"","table":null},{"a":"రావు బహద్దూర్ శ్యామలరెడ్డి","e":"","table":null},{"a":"హనుమంతరావు","e":"","table":null},{"a":"టేకుమల రంగారావు, మాడపాటి హనుమంతరావు, బూర్గుల రామకృష్ణారావు, కొండా వెంకటరంగారెడ్డి, మందుముల నరసింగరావు, మందుముల రామచంద్రరావు, ఆదిరాజు వీరభద్రరావు, పండిట రామస్వామి నాయుడు, ఆర్. రాజగోపాల రెడ్డి, మిట్టా లక్ష్మీనరసయ్య, కొమ్మవరపు సుబ్బారావు","e":"","table":null},{"a":"రాజ్యమంతా","e":"","table":null},{"a":"నగరంలోనే","e":"","table":null},{"a":"విద్య, స్త్రీల వికాసం","e":"","table":null},{"a":"దక్షను భావం, దక్షను చరిత్ర, దక్షను రాజ్యం, దక్షను సంస్కృతి","e":"","table":null},{"a":"మూసీనదిలో మూర్తీభవించింది","e":"","table":null},{"a":"1923 జూలై 27","e":"","table":null},{"a":"హైదరాబాద్‌లో మాడపాటి హనుమంతరావు నివాసగృహంలో","e":"","table":null},{"a":"ఏడుగురు","e":"","table":null},{"a":"ఆర్గురు","e":"","table":null},{"a":"రాజా బహద్దూర్ వెంకటరామారెడ్డి","e":"","table":null},{"a":"విద్యార్థులకు సహాయమందించి, ప్రోత్సహించాలి","e":"","table":null},{"a":"సంపాదించి వాటిపై పరిశోధన జరపాలి","e":"","table":null},{"a":"అత్యవసర సహాయం","e":"","table":null},{"a":"1924 మార్చి 21","e":"","table":null},{"a":"సుల్తానాబాద్‌లో (సల్లగొండలో)","e":"నీలగిరి పత్రిక సంపాదకులు షబ్బీసు వెంకట రామనరసింహారావు కార్యాలయ ఆవరణలో సల్లగొండలో జరిగింది.","table":null},{"a":"రావుబహద్దూర్ వెంకటరెడ్డి","e":"","table":null},{"a":"7గురు","e":"","table":null},{"a":"50 మంది","e":"","table":null},{"a":"చిత్రాద జమీందారు చెలికాని లచ్చారావు, శతక కవుల చరిత్ర గ్రంథకర్త వంగూరు సుబ్బారావు","e":"","table":null},{"a":"ప్రచారకుని","e":"","table":null},{"a":"''నిజాం రాష్ట్ర ఆంధ్రనిధి'' ఏర్పాటు చేయాలని, వెంకటరంగారెడ్డిని వ్యవహర్తగా ఉండాలని","e":"","table":null},{"a":"''లక్ష్మణరాయ పరిశోధక మండలి''","e":"","table":null},{"a":"బంగారు, వెండి పతకాలు","e":"","table":null},{"a":"500 రూపాయలు (కల్దారు)","e":"","table":null},{"a":"ఆంధ్ర విశ్వవిద్యాలయ సంబంధిత కళాశాలలో ప్రవేశించడానికి అనుమతించాలని","e":"","table":null},{"a":"1925 ఫిబ్రవరి 21","e":"","table":null},{"a":"వరంగల్లు జిల్లా మధిరలో పింగళి వెంకటరామారెడ్డి కర్మాగారపు ఆవరణలోని విశాలమైన మంటపంలో","e":"","table":null},{"a":"హైకోర్టు వకీలు మాడపాటి తిరుమలరావు","e":"","table":null},{"a":"మునగాల రాజా నారాయణ వెంకటరంగారావుగారి","e":"","table":null},{"a":"గద్వాల సంస్థానాధీశులు సీతారాం భూపాలు, జోగిపేట వర్తకుడు, ప్రజాకార్యకర్త శివప్ప గారు","e":"","table":null},{"a":"ప్రొఫెసరు శిరుగూరి హనుమంతరావు","e":"","table":null},{"a":"ఆదిరాజు వీరభద్రరావు","e":"","table":null},{"a":"నాయని వెంకటరంగారావు","e":"","table":null},{"a":"స్వర్ణ పతకములు","e":"","table":null},{"a":"25 రూపాయలు","e":"","table":null},{"a":"1928 మే నెల 28, 29, 30 తేదీలలో","e":"","table":null},{"a":"సూర్యాపేటలో","e":"","table":null},{"a":"కోదాటి రామకృష్ణారావు","e":"","table":null},{"a":"రాజకీయ విషయములు, రాజభక్తి విరుద్ధమైన విషయములు ముచ్చటించకూడదు","e":"","table":null},{"a":"సభాస్థానమున చుట్టలు, బీడీలు, సిగరెట్లు తాగరాదు, నిషేధ వస్తువులు సేవించరాదు","e":"","table":null},{"a":"నిబంధనలకు విరుద్ధంగా ప్రవర్తించే వారిపై చర్యతీసుకునే అధికారం ఆహ్వాన సంఘానికి ఉంటుంది","e":"","table":null},{"a":"ఉపన్యాసకులు ముందుగా తమ పేర్లను ఆహ్వాన సంఘానికి తెలియజేయాలి","e":"","table":null},{"a":"కొండా వెంకటరంగారె