యాబోధన, ఉన్నత విద్యకు ప్రభుత్వం పరిమితి విధించకుండా వ్యాప్తిచేసేందుకు కృషి, మద్యపాన నిషేధం","e":"","table":null},{"a":"పూర్తిగా, కొంతవరకు","e":"","table":null},{"a":"వారి భోజనానికి కావలసిన సామాగ్రి","e":"","table":null},{"a":"వర్తకులు","e":"","table":null},{"a":"''వంతుపద్ధతి''","e":"","table":null},{"a":"వర్తక సంఘాలు","e":"","table":null},{"a":"ప్రచురించబడింది","e":"","table":null},{"a":"ప్రభుత్వ దృష్టికి","e":"","table":null},{"a":"జబర్దస్తీ","e":"","table":null},{"a":"ప్రభుత్వోద్యోగులు నిరుత్తరులై పోయేవారు","e":"","table":null},{"a":"కృషిచేసింది","e":"","table":null},{"a":"కుమ్మరి నీళ్ళు తేవాలి, వంట చేయాలి, చాకలి పాత్రలు కడగాలి, బట్టలు ఉతకాలి","e":"","table":null},{"a":"మోసుకుపోవాలి","e":"","table":null},{"a":"కారు (ఇచ్చేవారు కారు)","e":"","table":null},{"a":"ప్రబోధం","e":"","table":null},{"a":"వర్తకుల ఇబ్బందులు తొలగిపోయినంత సులభంగా కాదు, చివరకు కాంగ్రెస్ ఆధ్వర్యాన ప్రజా ప్రభుత్వం ఏర్పాటైన తరువాతే","e":"","table":null},{"a":"ఒక భాగంగా","e":"","table":null},{"a":"సహపంక్తి భోజనాలు, అస్పృశ్యతా నివారణ, స్త్రీ విద్య, వితంతు వివాహాలు, రజస్వలానంతర వివాహాలు, కుల ప్రస్తక్తి లేకుండా, భాషా పరిధులను బట్టి ఉద్యమాల్ని నడపడం","e":"","table":null},{"a":"స్వతంత్రంగానే","e":"","table":null},{"a":"అఖిలభారత మహిళాసభ","e":"","table":null},{"a":"బలపరిచారు","e":"","table":null},{"a":"వితంతు వివాహాలను","e":"","table":null},{"a":"బహుభార్యాత్వాన్ని, కన్యాశుల్క్యాన్ని, వేశ్యావృత్తిని","e":"","table":null},{"a":"భాగం","e":"","table":null},{"a":"ప్రాతినిధ్యం","e":"","table":null},{"a":"ఒక్క పర్యాయం మాత్రమే","e":"","table":null},{"a":"తెలంగాణావారే","e":"","table":null},{"a":"ఆంధ్రులకు","e":"","table":null},{"a":"దేవాలయాలు","e":"","table":null},{"a":"మరమ్మతులు","e":"","table":null},{"a":"సభలు, సమావేశాలు","e":"","table":null},{"a":"శ్రీమతి కజిన్స్","e":"","table":null},{"a":"అఖిల భారత మహిళాసభ","e":"","table":null},{"a":"మహిళా విద్యా, సాంఘిక సంఘం","e":"","table":null},{"a":"ధన్‌రాజ్ గిర్జీని","e":"","table":null},{"a":"నిమగ్నులై ఉండేవారు","e":"","table":null},{"a":"కొన్ని ఆకర్షణీయమైన కార్యక్రమాలు","e":"","table":null},{"a":"అధ్యక్షురాలిగాను, పాట్రన్‌గాను","e":"","table":null},{"a":"వారు (సంబంధిత వనితలు)","e":"","table":null},{"a":"రంగమ్మ ఓబులరెడ్డి, రాణి సరళాదేవి, సుందరమ్మ","e":"","table":null},{"a":"జాతీయోద్యమంలో","e":"","table":null},{"a":"''ఆంధ్ర యువతీమండలి''","e":"","table":null},{"a":"ఆంధ్ర యువతీమండలి స్థాపనకు","e":"","table":null},{"a":"''ఆంధ్ర యువతీమండలి''","e":"","table":null},{"a":"1935లో","e":"","table":null},{"a":"15 సంవత్సరాలు","e":"","table":null},{"a":"''కమిటీ''లో","e":"","table":null},{"a":"కోశాధికారి","e":"","table":null},{"a":"సంయుక్త కార్యదర్శి","e":"","table":null},{"a":"రెడ్డి హాస్టల్","e":"","table":null},{"a":"పంపేవారు","e":"","table":null},{"a":"స్వంత స్థలం","e":"","table":null},{"a":"ఒక ప్రైమరీ స్కూలు","e":"","table":null},{"a":"హైస్కూలుగా","e":"","table":null},{"a":"శిశు వికాస్ విహార్, తరువాత క్రమేపీ స్త్రీల హాస్టళ్ళు, లైబ్రరీ, కుట్టుపని శిక్షణా కేంద్రం","e":"","table":null}]') ON CONFLICT(chapter_slug) DO UPDATE SET subject_id=excluded.subject_id, chapter_number=excluded.chapter_number, title=excluded.title, answers_json=excluded.answers_json;
INSERT INTO chapter_content (chapter_slug, subject_id, chapter_number, title, answers_json) VALUES ('chapter-18-vidya-vignanam-samskruti', 'telangana-history-te', 18, 'విద్య, విజ్ఞానం, సంస్కృతి', '[{"a":"నిజాం ప్రభుత్వమే","e":"విద్యా వ్యవస్థపై ప్రభుత్వానికి పూర్తి గుత్తాధికారం ఉండేది.","table":null},{"a":"చాలా అరుదు","e":"ప్రభుత్వం వాటిని అనుమతించేది కాదు.","table":null},{"a":"తెలుగు","e":"ప్రారంభంలో ఉర్దూ విద్యావిధానం ఉన్నా కింది తరగతుల్లో తెలుగు పుస్తకాలు కొనసాగించారు.","table":null},{"a":"కందుకూరి వీరేశలింగం పంతులు","e":"","table":null},{"a":"ఉర్దూ","e":"క్రమంగా మొదటి తరగతి నుంచి ఉర్దూలో విద్యావిధానం కొనసాగింది.","table":null},{"a":"రెండవ భాషగా","e":"","table":null},{"a":"ఉత్తర హిందూస్థానం","e":"","table":null},{"a":"కఠినంగా","e":"దీనివల్ల తెలుగు విద్యార్థులకు పాఠాలు అర్థం చేసుకోవడం కష్టంగా ఉండేది.","table":null},{"a":"సంస్థానంలోనే (హైదరాబాద్ సంస్థానం)","e":"","table":null},{"a":"ముస్లిం చక్రవర్తులు, రాజులు","e":"వారి ప్రధానులు, దర్బారుల్లోని విద్యావంతుల వర్ణన హెచ్చుగా ఉండేది.","table":null},{"a":"ఇస్లాం మతం","e":"","table":null},{"a":"రాజా బీర్బల్, రాజా తాన్సేన్","e":"","table":null},{"a":"హిందూ యుగం, ముస్లిం యుగం, బ్రిటిష్ యుగం","e":"ఇది బ్రిటిష్ వారు పెట్టిన విభజన పద్ధతి.","table":null},{"a":"నిజాం నవాబు, అతని పూర్వుల చరిత్ర","e":"","table":null},{"a":"బోధనాంశంగా","e":"","table":null},{"a":"ఉర్దూలో","e":"","table":null},{"a":"ఉర్దూలోకి","e":"","table":null},{"a":"పార్సీ, అరబ్బీ","e":"","table":null},{"a":"ఇతర రాష్ట్రాల నుంచి","e":"","table":null},{"a":"ఒకటి (ఒకటి మాత్రమే)","e":"ఇది జాతీయ భాషగా, ప్రజల మాతృభాషగా ఉండేది కాదు.","table":null},{"a":"తెలుగు, మరాఠీ, కన్నడం","e":"","table":null},{"a":"ప్రత్యామ్నాయంగా, పరాయి భాషాధిపత్యంగా","e":"దీనివల్ల తెలుగువారిలో విద్యావృద్ధి తగ్గిపోయింది.","table":null},{"a":"విశ్వకవి టాగూరు నుంచి రాజాజీ వరకు","e":"","table":null},{"a":"కాంగ్రెస్ ప్రభుత్వం ఏర్పడ్డాక","e":"","table":null},{"a":"ప్రభుత్వ వ్యతిరేకులుగా","e":"","table":null},{"a":"1940","e":"","table":null},{"a":"బ్రిటిష్ వారికి","e":"తాను స్వతంత్రుడనని చెప్పుకున్నా వాస్తవానికి సామంతుడే.","table":null},{"a":"సికింద్రాబాద్","e":"","table":null},{"a":"రెసిడెంట్","e":"","table":null},{"a":"హైదరాబాద్ నగరం","e":"అక్కడి నుంచి నిజాం పరిపాలనా వ్యవహారాలు తెలుసుకుని ఢిల్లీలోని బ్రిటిష్ ప్రభుత్వానికి రిపోర్టు చేసేవాడు.","table":null},{"a":"రాజకీయ ఉద్యమాలను అణచివేయడానికి","e":"నిజాంకు, బ్రిటిష్ వారికి వ్యతిరేకమైన ఉద్యమాలు తలెత్తకుండా చేయడానికి ఈ దిగ్బంధనాన్ని ఉపయోగించారు.","table":null},{"a":"సర్ వాల్టర్ మాంక్టన్","e":"","table":null},{"a":"లక్షల రూపాయలు","e":"","table":null},{"a":"వేల రూపాయలు","e":"","table":null},{"a":"30 సంవత్సరాలు","e":"","table":null},{"a":"1948","e":"పోలీసు చర్య అనంతరం పదవి విరమించి లండన్ వెళ్లిపోయాడు.","table":null}]') ON CONFLICT(chapter_slug) DO UPDATE SET subject_id=excluded.subject_id, chapter_number=excluded.chapter_number, title=excluded.title, answers_json=excluded.answers_json;
INSERT INTO chapter_content (chapter_slug, subject_id, chapter_number, title, answers_json) VALUES ('chapter-19-grandhalayalu', 'telangana-history-te', 19, 'గ్రంథాలయాలు', '[{"a":"1901","e":"హైదరాబాద్ నగరంలో స్థాపించబడింది.","table":null},{"a":"కొమర్రాజు వెంకటలక్ష్మణరావు","e":"","table":null},{"a":"రావిచెట్టు రంగారావు","e":"","table":null},{"a":"రాజా నాయని వెంకటరంగారావు","e":"మునగాల జమీందారు.","table":null},{"a":"ఆసఫియా స్టేట్ లైబ్రరీ","e":"","table":null},{"a":"అబ్దుల్ ఖయ్యూం","e":"","table":null},{"a":"మౌల్వీ సయ్యద్ హుసేన్ బిల్‌గ్రామీ","e":"","table":null},{"a":"ఇమాదుల్ ముల్క్","e":"","table":null},{"a":"స్టేట్ సెంట్రల్ లైబ్రరీ, అఫ్జల్‌గంజ్ ప్రాంతం","e":"","table":null},{"a":"భారత గుణవర్ధక సంస్థ","e":"పాతనగరంలో స్థాపించారు, ఇందులో ప్రాచీన కవుల రచనలు ఉన్నాయి.","table":null},{"a":"1908","e":"","table":null},{"a":"మాడపాటి హనుమంతరావు","e":"ఆంధ్ర పితామహుడిగా పేరొందారు.","table":null},{"a":"ఆంధ్ర సంవర్ధనీ గ్రంథాలయం","e":"","table":null},{"a":"మహబూబియా గ్రంథాలయం","e":"","table":null},{"a":"ఆంధ్ర విజ్ఞాన ప్రకాశన గ్రంథాలయం","e":"","table":null},{"a":"ఆంధ్ర సరస్వతీ గ్రంథాలయం","e":"","table":null},{"a":"ఇరువయ్యో శతాబ్దం","e":"","table":null},{"a":"సుమారు 15","e":"","table":null},{"a":"శబ్దానుశాసన గ్రంథాలయం","e":"","table":null},{"a":"జ్ఞాన విద్యుత్ ప్రవాహిణీ భాషానిలయం","e":"","table":null},{"a":"సిద్ధిమల్లేశ్వర గ్రంథాలయం","e":"","table":null},{"a":"ఆంధ్ర సరస్వతీ గ్రంథ నిలయం","e":"","table":null},{"a":"బాలసరస్వతీ ఆంధ్ర గ్రంథాలయం","e":"","table":null},{"a":"వేమన ఆంధ్ర భాషానిలయం","e":"","table":null},{"a":"పత్రికలు, పుస్తకాలు","e":"","table":null},{"a":"గ్రంథాలయాలు","e":"","table":null},{"a":"ఆంధ్ర ప్రకాశినీ గ్రంథాలయం","e":"సూర్యాపేటలోని గ్రంథాలయాన్ని అప్పటి కలెక్టర్ పరిశీలించాడు.","table":null},{"a":"ప్రభుత్వ అనుమతి తీసుకున్నారా అని","e":"","table":null},{"a":"గ్రంథాలయాన్ని మూసివేయమని","e":"","table":null},{"a":"సర్ అక్బర్ హైదరీ","e":"","table":null},{"a":"జిల్లా లోకల్ ఫండు బోర్డు అధ్యక్షుడు","e":"","table":null},{"a":"గ్రంథాలయాలు నడపడానికి ప్రభుత్వ అనుమతి పొందవలసిన అవసరం లేదు","e":"","table":null},{"a":"ఒక సంవత్సరం","e":"","table":null},{"a":"తెలుగు భాషను గుంజవలసిన అవసరం లేదని","e":"సర్కారు వారి దస్తరములతో వ్యవహారమంతా ఉర్దూ భాషలో ఉండగా, చచ్చిపోయిన తెలుగు భాషను గుర్తుచేసుకోవాల్సిన అవసరం లేదని అన్నాడు.","table":null},{"a":"శతావధాని కృష్టమాచార్యులు","e":"","table":null},{"a":"విక్రయించి పుస్తకాలు, పత్రికలు కొన్నారు","e":"","table":null},{"a":"సంచార గ్రంథాలయాలు","e":"","table":null},{"a":"సర్కారీ దవాఖానాలో డాక్టరు","e":"మహారాష్ట్రుడు, ప్రజల మనస్తత్వాన్ని గ్రహించి సమారాధన పేరుతో నిధులు సేకరించాడు.","table":null},{"a":"గజాల స్థలం, పెంకుటిల్లు","e":"","table":null},{"a":"గోదావరి వచనాలయము","e":"","table":null},{"a":"అణాగ్రంథమాలలు","e":"","table":null},{"a":"ఐదు రూపాయలు (అణా)","e":"","table":null},{"a":"హైదరాబాద్ రాజ్యాంగ సంస్కరణలు","e":"1939 నవంబరులో ప్రచురించారు.","table":null},{"a":"వెల్లుర్తి మాణిక్యరావు","e":"","table":null},{"a":"నిషేధం","e":"","table":null},{"a":"విజ్ఞాన ప్రచారిణీ గ్రంథమాల","e":"","table":null},{"a":"ధవళ శ్రీనివాసరావు, సరిప్రగడ భార్గవరావు","e":"","table":null},{"a":"1925","e":"మధిరలో జరిగింది.","table":null},{"a":"పింగళి వెంకట్రామిరెడ్డి","e":"","table":null},{"a":"దేశముఖ్","e":"జీతభత్యములు లేకుండా సెషన్స్ జడ్జి ఉద్యోగం చేసినవాడు.","table":null},{"a":"వామన్ నాయక్","e":"ప్రసిద్ధ మహారాష్ట్ర నాయకుడు, దాత.","table":null},{"a":"1929 మే 31, జూన్ 1","e":"","table":null},{"a":"దూపాటి వెంకటరమణాచార్యులు","e":"","table":null},{"a":"పోతన","e":"వరంగల్లే పోతన జన్మస్థలమని నిర్ధారించారు.","table":null},{"a":"కోదాటి నారాయణరావు","e":"","table":null},{"a":"విజ్ఞాన చంద్రిక గ్రంథమాల","e":"","table":null},{"a":"హైదరాబాద్‌లోని రెసిడెన్సీ బజార్","e":"రావిచెట్టు రంగారావు ఇంట్లో ఉండేది.","table":null},{"a":"మద్రాసుకు","e":"","table":null},{"a":"ఆదిరాజు వీరభద్రరావు","e":"","table":null},{"a":"ఆంధ్ర జనసంఘం","e":"","table":null},{"a":"లక్ష్మణరావు","e":"కొమర్రాజు వారి అస్తమయానంతరం పరిశోధక మండలిగా మారారు.","table":null},{"a":"రెండు సంపుటాలు","e":"","table":null},{"a":"1952","e":"","table":null},{"a":"దాశరథి","e":"","table":null},{"a":"ఆచార్య లక్ష్మీరంజనం","e":"సి. నారాయణరెడ్డి, కాళోజీ తదితరులతో పాటు సంఘం పరిపుష్టి చెందింది.","table":null},{"a":"సురవరం ప్రతాపరెడ్డి","e":"","table":null},{"a":"తెలంగాణలో కవులు లేరనే అభిప్రాయం","e":"తెలంగాణలో ఎవ్వరు తెలుగు మాట్లాడరని, తెలంగాణలో కవులు లేరని కొందరు అనుకునేవారు.","table":null},{"a":"వట్టికోట ఆళ్వారుస్వామి","e":"","table":null},{"a":"బూర్గుల రంగనాథరావు","e":"","table":null},{"a":"భాస్కరభట్ల కృష్టారావుగారు","e":"","table":null},{"a":"1943 మే 26","e":"రెడ్డి హాస్టల్ గ్రంథాలయ భవనంలో జరిగింది.","table":null},{"a":"లోకనంది శంకరనారాయణరావుగారు","e":"","table":null},{"a":"హైదరాబాద్ ఆంధ్ర సాహిత్య పరిషత్తు","e":"","table":null},{"a":"రాయప్రోలు సుబ్బారావు","e":"","table":null},{"a":"మహమ్మద్ ఖాసింఖాన్","e":"","table":null},{"a":"కురుగంటి సీతారామయ్య (రాఖాసి)","e":"","table":null},{"a":"నిజాంరాష్ట్ర ఆంధ్ర సారస్వత పరిషత్తు","e":"","table":null},{"a":"11 మంది","e":"","table":null},{"a":"బుక్కపట్టణం రామానుజాచార్యులు","e":"","table":null},{"a":"సురవరం ప్రతాపరెడ్డి","e":"","table":null},{"a":"1943 జూన్ 1, రెడ్డి హాస్టల్ గ్రంథాలయం","e":"","table":null},{"a":"లోకనంది శంకరనారాయణరావుగారు","e":"","table":null},{"a":"బిదురు వేంకటశేషయ్య","e":"","table":null},{"a":"సురవరం ప్రతాపరెడ్డి","e":"","table":null},{"a":"వరంగల్లు పట్టణం","e":"","table":null},{"a":"ఉదయరాజు రాజేశ్వరరావుగారు","e":"","table":null},{"a":"కాళోజీ నారాయణరావు","e":"","table":null},{"a":"నల్లగొండలో","e":"కంచనపల్లి చిన వెంకటరామారావుగారు సభాధ్యక్షత వహించారు.","table":null},{"a":"ఇల్లిందల రామచంద్రరావుగారు","e":"దేవులపల్లి రామానుజరావుగారి మిత్రుడు.","table":null},{"a":"వేసిన పందిళ్లను","e":"","table":null},{"a":"ఎం.ఎస్. రాజలింగంగారు","e":"తన యువక సంఘంతో వెళ్లి సభాస్థలిని బాగుచేశారు.","table":null},{"a":"రాజకీయ అనిశ్చితి","e":"","table":null},{"a":"సహించలేకపోయింది","e":"దౌర్జన్యాలు కూడా జరిగాయి.","table":null},{"a":"1947 ఆగస్టు 15","e":"","table":null},{"a":"స్వతంత్రుడని","e":"","table":null},{"a":"రాష్ట్రం విడిచి సురక్షిత ప్రాంతానికి వెళ్లిపోయారు","e":"","table":null},{"a":"దేవులపల్లి రామానుజరావు","e":"మొక్కను పెంచి మానును చేశారు.","table":null},{"a":"డా. సి. నారాయణరెడ్డి","e":"","table":null},{"a":"నిరక్షరాస్యత","e":"","table":null},{"a":"పారి భాషిక, మాండలిక కోశాలు","e":"","table":null},{"a":"చెన్నారెడ్డి, పి.వి.","e":"","table":null}]') ON CONFLICT(chapter_slug) DO UPDATE SET subject_id=excluded.subject_id, chapter_number=excluded.chapter_number, title=excluded.title, answers_json=excluded.answers_json;
INSERT INTO chapter_content (chapter_slug, subject_id, chapter_number, title, answers_json) VALUES ('chapter-2-ikshvaku', 'telangana-history-te', 2, 'ఇక్ష్వాకులు', '[{"a":"వాసిష్టీ పుత్ర శ్రీచాంతమూలుడు","e":"శాతవాహన సామ్రాజ్యం అంతరించాక కృష్ణాతీరంలో విజయపురి రాజధానిగా ఈ వంశరాజ్యం స్థాపించాడు.","table":null},{"a":"విజయపురి","e":"దీన్నే నేటి నాగార్జునకొండ అంటారు.","table":null},{"a":"225-300 మధ్య","e":"","table":null},{"a":"శాంతిమూలుడు, వీర పురుషదత్తుడు, ఏహువల శాంతమూలుడు, రుద్రపురుష దత్తుడు","e":"","table":null},{"a":"గుంటూరు, ప్రకాశం, నల్లగొండ మండలాలు","e":"","table":null},{"a":"వైదిక మతం","e":"","table":null},{"a":"మహాసేన, విరూపాక్షాలయాలు","e":"","table":null},{"a":"రాణివాసపు స్త్రీలు, రాణులు","e":"","table":null},{"a":"శాతవాహన పద్ధతి","e":"","table":null},{"a":"సింహం","e":"","table":null},{"a":"చైనా, సింహళం, మలయా దేశాలు","e":"","table":null},{"a":"బౌద్ధతీర్థము","e":"","table":null},{"a":"ప్రాకృతభాష","e":"","table":null},{"a":"పంచాంగం, చంద్రాయన వ్యవహారము","e":"తిథి, వార, పక్ష, మాసాలతో కూడిన పంచాంగం, చంద్రాయన వ్యవహారము వీరి కాలంనుండే ప్రారంభమైనది.","table":null},{"a":"గ్రీష్మము, వర్షము, హేమంతము","e":"ఒక్కో ఋతువుకు నాలుగు మాసాలు.","table":null},{"a":"వైవాహిక సంబంధాలు","e":"","table":null},{"a":"నాగార్జునకొండ త్రవ్వకాలలో లభించిన పురావస్తు సంపద","e":"","table":null},{"a":"వెలుపల చెక్కరాయి, మట్టి ఇటుకలు","e":"","table":null},{"a":"రంగభూమి","e":"గోళాకారమైన ఈ కట్టడంలో దాదాపు వేయిమంది ప్రేక్షకులు కూర్చుని చూడగలిగేవారు.","table":null},{"a":"రోమన్ నాణేలు","e":"విదేశాలతో విజయపురికి వర్తక వ్యాపారాలు విరివిగా సాగినట్లు తెలుస్తుంది.","table":null},{"a":"ఇక్ష్వాకు వంశం","e":"","table":null},{"a":"రుద్రపురుషదత్తుడు","e":"పల్లవరాజైన సింహవర్మ విజయపురిపై దండెత్తి ఇక్ష్వాకు రాజ్యాన్ని అంతరింపజేశాడు.","table":null},{"a":"విశ్వవిద్యాలయంగా","e":"నాగార్జునుని కాలం నుండి కొన్ని శతాబ్దాల వరకు విద్యార్థుల విద్యాదాహాన్ని తీర్చే కేంద్రంగా నిలిచింది.","table":null},{"a":"కాశ్మీర్, గాంధార, చీన, చిలాటి, తోసలి, అపరాంత, వంగ, వారణాసి, యవన, సాలూర, తంబపణ్ణి, తమిళ దేశాలు","e":"","table":null}]') ON CONFLICT(chapter_slug) DO UPDATE SET subject_id=excluded.subject_id, chapter_number=excluded.chapter_number, title=excluded.title, answers_json=excluded.answers_json;
INSERT INTO chapter_content (chapter_slug, subject_id, chapter_number, title, answers_json) VALUES ('chapter-20-patrikalu', 'telangana-history-te', 20, 'పత్రికలు', '[{"a":"ఉర్దూ","e":"","table":null},{"a":"శ్రీనివాసశర్మ","e":"","table":null},{"a":"హిత బోధిని","e":"","table":null},{"a":"వ్యవసాయం, వైద్యం, పారిశ్రామిక, సంఘసంస్కరణ","e":"రాజకీయాల ప్రవేశం లేకుండా ఈ నాలుగు అంశాలపై పత్రిక నడిచింది.","table":null},{"a":"500 మంది","e":"","table":null},{"a":"ఆయుర్వేద వైద్యుడు","e":"","table":null},{"a":"2 సంవత్సరాలు","e":"శ్రీనివాసశర్మ సాంస్కృతిక కార్యక్రమాల్లో మునిగిపోవడం వల్ల పత్రిక ఆగిపోయింది.","table":null},{"a":"ఆంధ్ర మరము","e":"","table":null},{"a":"జగదీశ్వర ప్రింటింగ్ ప్రెస్ (గోల్కొండ)","e":"","table":null},{"a":"ఆధ్యాత్మిక జ్ఞానం","e":"","table":null},{"a":"1922","e":"","table":null},{"a":"పబ్బువీసు వెంకటరామనరసింహారావు","e":"","table":null},{"a":"మొట్టమొదటి పూర్తిస్థాయి రాజకీయ పత్రిక","e":"","table":null},{"a":"తెనుగు పత్రిక","e":"","table":null},{"a":"వొద్దిరాజు సీతారామచంద్రరావు, వొద్దిరాజు రాఘవరంగారావు","e":"వీరిద్దరూ సోదరులు.","table":null},{"a":"పబ్బువీసు రామనరసింహారావు","e":"","table":null},{"a":"మాడపాటి హనుమంతరావు, బుర్గుల రామకృష్టారావు, పులిజాల రంగారావు","e":"","table":null},{"a":"గుడిపాటి వెంకటాచలం","e":"","table":null},{"a":"1929","e":"","table":null},{"a":"వొద్దిరాజు సోదరులు","e":"","table":null},{"a":"ఇనుగుర్తి (మానుకోట తాలూకా)","e":"","table":null},{"a":"స్థానిక యువకులు","e":"","table":null},{"a":"మహబూబాబాద్","e":"","table":null},{"a":"వార్తాపత్రికలు","e":"రేడియో, టీవీలు అప్పటికి లేవు.","table":null},{"a":"5 సంవత్సరాలు","e":"","table":null},{"a":"విజ్ఞాన ప్రచారిణి గ్రంథమాల","e":"","table":null},{"a":"సురవరం ప్రతాపరెడ్డి","e":"","table":null},{"a":"ద్వైవారపత్రిక","e":"","table":null},{"a":"1947","e":"","table":null},{"a":"గుండెల్లో కుంపటి","e":"","table":null},{"a":"శైవప్రచారిణి","e":"","table":null},{"a":"తెనుగు పత్రిక","e":"","table":null},{"a":"సుజాత; నాల్గవ సంవత్సరం మొదటి సంచికతో","e":"","table":null},{"a":"ఆంధ్రకేసరి","e":"ఇది ఆంగ్ల-తెలుగు భాషల్లో వెలువడేది.","table":null},{"a":"5 సంవత్సరాలు","e":"","table":null},{"a":"బెల్లంకొండ రామానుజాచార్యులు, నరసింహాచార్యులు","e":"వీరు సోదరులు, వడ్డేపల్లి గ్రామం (ఆత్రాఫ్‌బల్దా జిల్లా) నుండి.","table":null},{"a":"నల్లగొండ (రామన్నపేట తాలూకా)","e":"","table":null},{"a":"తెలుగు, సంస్కృతం, ఇంగ్లీషు","e":"","table":null},{"a":"పబ్బువీసు వెంకటరామ నరసింహారావు, మాడపాటి హనుమంతరావు","e":"నీలగిరి పత్రిక వద్ద శిక్షణ పొందారు.","table":null},{"a":"బెజవాడ, ఆంధ్రవాణి","e":"ఐదు సంవత్సరాలు ఆంధ్రవాణి పత్రికను నడిపారు.","table":null},{"a":"ఆంధ్రవాణి వీధి","e":"","table":null},{"a":"1970","e":"","table":null},{"a":"హైదరాబాద్ బులెటిన్","e":"","table":null},{"a":"రామానుజాచార్యులు","e":"","table":null},{"a":"1942; రామానుజాచార్యులు","e":"","table":null},{"a":"చార్మినార్ గాసిప్","e":"","table":null},{"a":"నవాబు అంతఃపుర విషయాలు, ఉన్నతాధికారవర్గం కార్యాలయాల రహస్యాలు","e":"","table":null},{"a":"దక్కన్ క్రానికల్","e":"","table":null},{"a":"1939","e":"","table":null},{"a":"గారిసన్","e":"","table":null},{"a":"డెయిలీ న్యూస్","e":"","table":null},{"a":"నెలరోజులు","e":"","table":null},{"a":"భాగ్యనగర్","e":"","table":null},{"a":"భాగ్యరెడ్డి అనారోగ్యం (మైసూరు వెళ్లడం)","e":"","table":null},{"a":"ఆది హిందూ","e":"","table":null},{"a":"వీరభద్రశర్మ","e":"","table":null},{"a":"శోభ","e":"","table":null},{"a":"ఆర్థిక కారణాలు","e":"","table":null},{"a":"నిజాం క్రూర నిర్బంధం (వాక్ స్వాతంత్ర్యంపై)","e":"","table":null},{"a":"తరణి","e":"","table":null},{"a":"ఖాజా అబ్దుల్ గఫార్","e":"","table":null},{"a":"సందేశం; ఆరు నెలలు","e":"","table":null},{"a":"మీజాన్","e":"","table":null},{"a":"ఇంగ్లీషు, ఉర్దూ, తెలుగు","e":"","table":null},{"a":"నిజాం ప్రభుత్వం","e":"","table":null},{"a":"లీగ్‌ను, రజాకార్లను","e":"","table":null},{"a":"నిజాం వ్యతిరేక శక్తులను","e":"","table":null},{"a":"అడవి బాపిరాజు","e":"","table":null},{"a":"తిరుమల రామచంద్ర, రాంభట్ల కృష్ణమూర్తి, శ్రీనివాస చక్రవర్తి, బొమ్మకంటి సుబ్బారావు, విద్వాన్ విశ్వం","e":"","table":null},{"a":"ధూపదీపాలు, మిర్చి మసాలా","e":"","table":null},{"a":"మూడు సంవత్సరాలు","e":"","table":null},{"a":"1947 ఆగస్టు 7","e":"","table":null},{"a":"మందుముల నరసింగరావు","e":"","table":null},{"a":"ఆంధ్ర మహాసభ","e":"","table":null},{"a":"రజాకార్లు","e":"","table":null},{"a":"ఇమ్రోజ్","e":"","table":null},{"a":"రజాకార్ల దౌష్ట్యాలు","e":"","table":null},{"a":"ఖాసిం రజ్వీ","e":"","table":null},{"a":"రజాకార్ దుర్మార్గులు","e":"","table":null}]') ON CONFLICT(chapter_slug) DO UPDATE SET subject_id=excluded.subject_id, chapter_number=excluded.chapter_number, title=excluded.title, answers_json=excluded.answers_json;
INSERT INTO chapter_content (chapter_slug, subject_id, chapter_number, title, answers_json) VALUES ('chapter-21-telangana-jalavanarulu-parishramalu', 'telangana-history-te', 21, 'తెలంగాణ జలవనరులు, పరిశ్రమలు', '[{"a":"భాష","e":"భాషా రాష్ట్రాల నిర్మాణానికి తెలంగాణ ప్రధాన కారణమైంది.","table":null},{"a":"ఆంధ్ర జాతీయ వికాసానికి కేంద్రం","e":"","table":null},{"a":"ఆసఫ్‌జాహీ వంశం","e":"","table":null},{"a":"1,200 అడుగులు","e":"","table":null},{"a":"ఆగ్నేయ దిశ","e":"","table":null},{"a":"ఆదిలాబాద్ జిల్లా","e":"","table":null},{"a":"నిర్మల్ కొండలు","e":"","table":null},{"a":"80 మైళ్ళు","e":"","table":null},{"a":"35-40 మైళ్ళు","e":"","table":null},{"a":"బాలాఘాటు పర్వత వరుస; నల్లగొండ జిల్లా (రాచకొండ గుట్టలు)","e":"","table":null},{"a":"ఎడమవైపు (గోదావరికి)","e":"","table":null},{"a":"అమ్రాబాద్ గుట్టలు","e":"","table":null},{"a":"వికారాబాద్ ప్రాంతం","e":"","table":null},{"a":"కృష్ణా, గోదావరి","e":"","table":null},{"a":"మంజీర","e":"","table":null},{"a":"బీడ్ జిల్లా","e":"","table":null},{"a":"400 మైళ్ళు","e":"","table":null},{"a":"ప్రాణహిత","e":"","table":null},{"a":"మానేరు","e":"","table":null},{"a":"సిరిసిల్ల కొండలు","e":"","table":null},{"a":"80 మైళ్ళు","e":"","table":null},{"a":"800 మైళ్ళు","e":"","table":null},{"a":"మహాబలేశ్వర్ సమీపం","e":"","table":null},{"a":"పాతాళగంగ","e":"","table":null},{"a":"సంగమేశ్వర్ (ఆలంపూర్ సమీపం)","e":"","table":null},{"a":"కుతుబ్‌షా మహమ్మద్ఖులీ","e":"గోల్కొండ నాలవ కుతుబ్‌షా.","table":null},{"a":"భాగ్యనగరం","e":"తన ప్రియురాలైన భాగమతి పేరిట నామకరణం చేశాడు.","table":null},{"a":"హైదర్‌మహల్ (భార్య పేరు)","e":"","table":null},{"a":"మూసీ నది","e":"","table":null},{"a":"సికింద్రాబాద్","e":"","table":null},{"a":"లష్కర్","e":"","table":null},{"a":"రెండు నదీ ప్రాంతాలు","e":"","table":null},{"a":"3","e":"","table":null},{"a":"పాఖాల, రామప్ప, లక్నవరం, ఘనపురం చెరువులు","e":"","table":null},{"a":"హుసేన్‌సాగర్","e":"","table":null},{"a":"మీరాలం చెరువు","e":"","table":null},{"a":"భారత ఇరిగేషన్ కమీషన్; ముఖ్య ప్రాజెక్టుల నిర్మాణం","e":"","table":null},{"a":"మూసీ నది