INSERT INTO chapter_content (chapter_slug, subject_id, chapter_number, title, answers_json) VALUES ('chapter-22-mulki-kathanam', 'telangana-history-te', 22, 'ముల్కీ కథనం', '[{"a":"దక్కనులోని రాజ్యాలను కూల్చివేసాయి","e":"","table":null},{"a":"ఆఫాఖీలు","e":"","table":null},{"a":"సూఫీమతం","e":"","table":null},{"a":"సున్నీలు","e":"","table":null},{"a":"బీదర్‌నగరం","e":"","table":null},{"a":"78 సంవత్సరాల వయోవృద్ధుడు","e":"","table":null},{"a":"ఖాజీ మహమ్మద్ గవాన్","e":"","table":null},{"a":"బహమనీ రాజ్యం శిథిలమైపోయింది","e":"","table":null},{"a":"కుతుబ్‌షాహీలు","e":"","table":null},{"a":"కులీ కుతుబ్‌షా; ఇరాన్‌లోని హమ్దాన్ రాజవంశం","e":"","table":null},{"a":"అబ్దుల్ హసన్ తానీషా","e":"","table":null},{"a":"సూర్యప్రకాశరావు","e":"","table":null},{"a":"300 సంవత్సరాలు","e":"","table":null},{"a":"అక్కన్న; రెవిన్యూ మంత్రి","e":"","table":null},{"a":"ముల్కీ నాన్‌ముల్కీల గొడవలు","e":"","table":null},{"a":"కుతుబ్‌షాహీ రాజ్యం పునాదులు కదిలాయి","e":"","table":null},{"a":"ముస్లింలను, ఉర్దూభాష మాట్లాడే కాయస్థులను","e":"","table":null},{"a":"అబుల్‌హసన్ షేర్ఖాన్ పాయోగా","e":"","table":null},{"a":"పాయోగా వారి వంశం","e":"","table":null},{"a":"మీర్ ఆలం, చందూలాల్, ఇమాదుల్ ముల్క్","e":"","table":null},{"a":"దేశద్రోహులుగా","e":"","table":null},{"a":"మొగల్ చక్రవర్తి","e":"","table":null},{"a":"అఫ్జలుద్దౌలాబహదూర్","e":"","table":null},{"a":"మైదటి సాలార్‌జంగ్","e":"","table":null},{"a":"ఫకీర్లు","e":"","table":null},{"a":"లంచమిచ్చి తమవైపు తిప్పుకున్నారు","e":"","table":null},{"a":"1880","e":"","table":null},{"a":"ఇంగ్లీషుకు","e":"","table":null},{"a":"సాలార్‌జంగ్","e":"","table":null},{"a":"రాష్ట్రోద్యోగుల సివిల్ లిస్టు","e":"","table":null},{"a":"246 మంది, 52 శాతం","e":"","table":null},{"a":"230 మంది, 48 శాతం","e":"","table":null},{"a":"42 శాతం","e":"","table":null},{"a":"58 శాతం","e":"","table":null},{"a":"97 మంది (20%, వేతనం 24%)","e":"","table":null},{"a":"66 మంది (14%, వేతనం 11%)","e":"","table":null},{"a":"36 మంది (8%, వేతనం 8%)","e":"","table":null},{"a":"24 మంది (5%, వేతనం 13%)","e":"","table":null},{"a":"15 రబీ ఉల్‌సానీ","e":"","table":null},{"a":"నిజాం రాష్ట్రంలో పుట్టి ఉండాలి, లేదా ఇక్కడి మనిషిని వివాహం చేసుకొని ఉండాలి, లేదా పదిహేను సంవత్సరాలు నివాసంగా ఉండాలి","e":"","table":null},{"a":"ఉర్దూపదం; దేశము","e":"","table":null},{"a":"అవును","e":"ఉత్తరాది ఉర్దూను ''బాబాయె ఉర్దూ'' దా. అబ్దుల్ హక్ పోషించగా, దక్షిణీ ఉర్దూకు దా. ఖాదర్ మొహియుద్దీన్ జోర్ ఆచార్య పీఠం వహించేవారు.","table":null},{"a":"ఇదారా అద్బియత్ ఉర్దూ","e":"","table":null},{"a":"అంజుమనె తరక్కీ ఉర్దూ","e":"","table":null},{"a":"దారుల్ తర్జుమా","e":"","table":null},{"a":"పాకిస్తాన్","e":"","table":null},{"a":"హైదరాబాద్","e":"","table":null},{"a":"ఇంగ్లీషు","e":"","table":null},{"a":"ప్రాంతీయ భాషలు","e":"","table":null},{"a":"ముల్కీ సర్టిఫికెట్","e":"","table":null},{"a":"అనాగరికమైన ప్రాంతాన్ని నాగరికం చేయడానికి ప్రయత్నిస్తున్నట్లు","e":"","table":null},{"a":"విశ్వవిద్యాలయ స్థాయి","e":"","table":null},{"a":"తెలుగు, మరాఠీ, కన్నడం","e":"","table":null},{"a":"ఉర్దూ","e":"","table":null},{"a":"విద్యావ్యాప్తి తగ్గిపోయింది","e":"","table":null},{"a":"టాగూర్","e":"","table":null},{"a":"రాజగోపాలాచారి","e":"","table":null},{"a":"ఇంగ్లీషు","e":"","table":null},{"a":"విద్యావిధానం","e":"","table":null},{"a":"1941 ఏప్రిల్","e":"","table":null},{"a":"వినాయకరావు విద్యాలంకార్","e":"","table":null},{"a":"మాతృభాషలో","e":"","table":null},{"a":"ఇంగ్లీషు","e":"","table":null},{"a":"హిందీ, సంస్కృతం","e":"","table":null},{"a":"వందేమాతరం","e":"","table":null},{"a":"ఖాన్సీ స్కూళ్లు","e":"","table":null},{"a":"జోషి","e":"","table":null},{"a":"తెలుగు, మరాఠీ, కన్నడ","e":"","table":null},{"a":"ఖాన్సీ పాఠశాలలు","e":"","table":null},{"a":"అనవసరమైన ఉర్దూలో","e":"","table":null},{"a":"ఉచితంగా, నిర్బంధంగా","e":"","table":null},{"a":"ప్రజామండలి ప్రతినిధులకు","e":"","table":null},{"a":"ఆయా ప్రాంతాలలో అధికార భాషలుగా","e":"","table":null},{"a":"బూర్గుల రామకృష్ణారావు","e":"","table":null},{"a":"1944 నవంబర్ 11","e":"","table":null},{"a":"మాతృభాషలను బోధనా భాషలుగా చేయాలనే సూత్రం","e":"","table":null},{"a":"ఉర్దూలో బోధన జరపడం ఎంతవరకు సమ