INSERT INTO chapter_content (chapter_slug, subject_id, chapter_number, title, answers_json) VALUES ('chapter-23-majlis-ittehadul-muslimeen-rajakeeyalu', 'telangana-history-te', 23, 'మజ్లిస్ ''ఇత్తెహాదుల్ ముసల్మీన్'' రాజకీయాలు', '[{"a":"యాభై సంవత్సరాల హైదరాబాద్","e":"","table":null},{"a":"1926","e":"","table":null},{"a":"జాగీర్దార్లు, మన్సబ్‌దారులు","e":"","table":null},{"a":"హైదరాబాద్","e":"","table":null},{"a":"నవాబ్ వికారుల్ ముల్క్ బహదూర్","e":"","table":null},{"a":"అలీఘర్","e":"","table":null},{"a":"హిందువుల పాలితులు","e":"","table":null},{"a":"హైదరాబాద్","e":"","table":null},{"a":"పాకిస్తాన్","e":"","table":null},{"a":"ముసల్మానులందరినీ సంఘటితపరచడం, ఆర్థికాభివృద్ధికి తోడ్పడటం, ప్రభుభక్తిపరాయణులుగా తీర్చిదిద్దడం","e":"","table":null},{"a":"మహమ్మద్ ప్రవక్త జన్మదినోత్సవం","e":"","table":null},{"a":"1938","e":"","table":null},{"a":"ఆర్యసమాజ్","e":"","table":null},{"a":"బహదూర్ యార్ జంగ్","e":"","table":null},{"a":"ఉర్దూ","e":"","table":null},{"a":"హైదరాబాద్ ప్రభుత్వం సర్వస్వాతంత్ర్యం కలిగిన రాజాధికారిగా ఉండాలి","e":"","table":null},{"a":"ముస్లింలు","e":"","table":null},{"a":"బోధనాభాషగా, రాజభాషగా","e":"","table":null},{"a":"''అనిల్ మాలిక్''","e":"అంటే ''నేనే ప్రభువును'' అని అర్థం.","table":null},{"a":"అహమ్ బ్రహ్మాస్మీ","e":"","table":null},{"a":"ఉస్మాన్ అలీఖాన్","e":"","table":null},{"a":"తల్లీగ్","e":"","table":null},{"a":"బహదూర్ యార్ జంగ్","e":"","table":null},{"a":"20 వేల మంది","e":"","table":null},{"a":"88.9 శాతం","e":"","table":null},{"a":"84 శాతం","e":"","table":null},{"a":"శుద్ధి సంఘటన","e":"","table":null},{"a":"ఇనాయతుల్లా మష్రికీ","e":"","table":null},{"a":"బహదూర్ యార్ జంగ్","e":"","table":null},{"a":"కాక్సార్ ఉద్యమ నాయకత్వం","e":"","table":null},{"a":"మజ్లిస్ సంస్థ","e":"","table":null},{"a":"అయ్యంగార్ కమిటీ","e":"","table":null},{"a":"1939; సర్ అక్బర్ హైదరీ","e":"సర్ అక్బర్ హైదరీ నాటి సంస్థాన ప్రధాని.","table":null},{"a":"హిందూ-ముస్లిం లిద్దరికీ సమాన ప్రతిపత్తి కల్పించడం","e":"","table":null},{"a":"మజ్లిస్‌కు","e":"","table":null},{"a":"''హిజ్ మెజెస్టీ'' బిరుదు","e":"","table":null},{"a":"ముసల్మానులు","e":"","table":null},{"a":"ప్రత్యేక దేశంగా ముస్లిం రాజ్యంగా","e":"","table":null},{"a":"సర్కారు, సీడెడ్ జిల్లాలు నిజాం రాష్ట్రంలో కలిసిపోయి ''ఉస్మానిస్తాన్'' ఏర్పడుతుంది","e":"","table":null},{"a":"50 కోట్ల రూపాయలు","e":"","table":null},{"a":"సావర్కర్","e":"","table":null},{"a":"రాజ్యం మొదటి నిజాం స్వంత ఆస్తికాదని, 7వ నిజాం సొంత జాగీరు కాదని","e":"","table":null},{"a":"ముస్లిం ప్రజలందరి ఆస్తి","e":"","table":null},{"a":"ఒక సంవత్సరం","e":"","table":null},{"a":"జంగ్, బహదూర్","e":"చివరికి బహదూర్ యార్ఖాన్‌గానే మిగిలిపోయాడు.","table":null},{"a":"జాగీర్దారీ కుటుంబం","e":"","table":null},{"a":"మహమ్మద్ అలీ జిన్నా","e":"","table":null},{"a":"ఉర్దూలోకి","e":"","table":null},{"a":"లక్షరూపాయలు","e":"","table":null},{"a":"చందాలు ఇవ్వలేనివారు దేశం ఎలా సంపాదించుకుంటారు","e":"","table":null},{"a":"ఆలింగనం చేసుకున్నాడు","e":"","table":null},{"a":"నలభయ్యో ఏట","e":"","table":null},{"a":"ఒక మిత్రుని ఇంట్లో హఠాత్తుగా మరణించాడు","e":"","table":null},{"a":"హత్య జరిగిందని","e":"విచారణలో ఇది వెల్లడి కాలేదు.","table":null},{"a":"''ఖాయిదె ఆజం''","e":"","table":null},{"a":"''ఖాయిద్-ఎ-మిల్లత్''","e":"","table":null},{"a":"మజ్లిస్","e":"","table":null},{"a":"మజ్లిస్ రాజకీయ సంస్థ కాదని భావించారు","e":"","table":null}]') ON CONFLICT(chapter_slug) DO UPDATE SET subject_id=excluded.subject_id, chapter_number=excluded.chapter_number, title=excluded.title, answers_json=excluded.answers_json;
INSERT INTO chapter_content (chapter_slug, subject_id, chapter_number, title, answers_json) VALUES ('chapter-24-arya-samaj-poratalu', 'telangana-history-te', 24, 'ఆర్యసమాజ్ పోరాటాలు', '[{"a":"బలం","e":"","table":null},{"a":"ఉత్తర హిందూస్థానం","e":"","table":null},{"a":"ఆర్యులం","e":"","table":null},{"a":"దయానంద సరస్వతి","e":"","table":null},{"a":"శ్రద్ధానందుడు","e":"","table":null},{"a":"పండిత కేశవరావు కోరాట్కర్","e":"","table":null},{"a":"హైదరాబాద్ హైకోర్టు న్యాయమూర్తి","e":"","table":null},{"a":"1932","e":"","table":null},{"a":"1921","e":"","table":null},{"a":"1923","e":"","table":null},{"a":"సిద్దీకీ దీన్‌దార్","e":"","table":null},{"a":"మంగళ్‌దేవ్, పండిత రామచంద్ర దహేళ్వీలు","e":"","table":null},{"a":"హైదరాబాద్ రాష్ట్ర శాసనసభ","e":"","table":null},{"a":"హిందూ-ముస్లిం సభ్యులు","e":"","table":null},{"a":"పండిత వినాయకరావు విద్యాలంకార్","e":"","table":null},{"a":"1932 మే 21","e":"","table":null},{"a":"పండిత వినాయకరావు విద్యాలంకార్","e":"కేశవరావు కుమారుడు.","table":null},{"a":"పండిత రామచంద్ర దహేళ్వీ, చంద్రభాను","e":"","table":null},{"a":"1934","e":"","table":null},{"a":"నారాయణస్వామి, స్వామి స్వతంత్రానంద, ఆచార్య రాందేవులు","e":"","table":null},{"a":"హవన కుండాలను, మందిరాలను","e":"","table":null},{"a":"హోంశాఖ కార్యదర్శి జువైదర్‌జంగ్","e":"","table":null},{"a":"కలెక్టరు స్వంత ఖర్చులతో మందిరాలను, హవనకుండాలను నిర్మించి పెట్టవలసిందని","e":"","table":null},{"a":"1937","e":"","table":null},{"a":"1937","e":"","table":null},{"a":"21 మంది","e":"","table":null},{"a":"ధర్మప్రకాశ్‌ను","e":"","table":null},{"a":"శ్యాంలాల్‌ను","e":"","table":null},{"a":"డిసెంబర్ 17; బీదర్ జైలు","e":"","table":null},{"a":"1932","e":"","table":null},{"a":"పండిత నరేంద్రజీని","e":"","table":null},{"a":"మన్ననూరు జైలు","e":"","table":null},{"a":"''కాలాపానీ''","e":"","table":null},{"a":"మహబూబ్‌నగర్ జిల్లా (నల్లమల అడవులలో అమరాబాద్ సమీపం)","e":"","table":null},{"a":"మూడు సంవత్సరాలు","e":"","table":null},{"a":"వాగ్బంధనం","e":"","table":null},{"a":"అఖిలభారత ఆర్యమహాసభ","e":"","table":null},{"a":"హైదరాబాద్ సమస్య",