:"","table":null},{"a":"బీబీనగర్ కేసు","e":"","table":null},{"a":"ఏడు సంవత్సరాలు","e":"","table":null},{"a":"దాదాపు రక్తపాతంలేని దండయాత్ర","e":"","table":null},{"a":"నిజాం ఆట కట్టించాయి","e":"","table":null},{"a":"బందారం బయటపడింది","e":"అది పేకమేడలా కూలి, అతిగతి లేకుండా అంతర్ధానమైపోయింది.","table":null},{"a":"కాంగ్రెస్","e":"","table":null},{"a":"కాంగ్రెస్","e":"","table":null},{"a":"కమ్యూనిస్టు అనుకూల శక్తులు","e":"","table":null},{"a":"పండిట్ జవహర్‌లాల్ నెహ్రూ, సర్దార్ వల్లభాయ్ పటేల్","e":"","table":null},{"a":"తాత్కాలిక ప్రభుత్వం","e":"","table":null},{"a":"్ మేజర్-జనరల్ జె.ఎన్.చౌదరి","e":"","table":null},{"a":"మనస్ఫూర్తిగా","e":"","table":null},{"a":"మద్రాసు, బొంబాయి","e":"","table":null}]') ON CONFLICT(chapter_slug) DO UPDATE SET subject_id=excluded.subject_id, chapter_number=excluded.chapter_number, title=excluded.title, answers_json=excluded.answers_json;
INSERT INTO chapter_content (chapter_slug, subject_id, chapter_number, title, answers_json) VALUES ('chapter-4-chalukyulu', 'telangana-history-te', 4, 'చాళుక్యులు', '[{"a":"బాదామి కోట","e":"ఇది బీజాపూరు జిల్లాలో ఉంది.","table":null},{"a":"అశ్వమేధయాగం","e":"","table":null},{"a":"క్రీ.శ. 610","e":"","table":null},{"a":"హర్షవర్ధనుడు","e":"","table":null},{"a":"కుబ్జ విష్ణువర్ధనుడు","e":"","table":null},{"a":"విష్ణువర్ధనుడు","e":"","table":null},{"a":"క్రీ.శ. 631","e":"","table":null},{"a":"పులకేశిపై","e":"ఈ యుద్ధంలో పులకేశి, విష్ణువర్ధనులిద్దరు ప్రాణాలు కోల్పోయారు.","table":null},{"a":"జయసింహుడు","e":"ఇతను, తమ్ముడు ఇంద్రభట్టారకుడు ఒకరి తరువాత ఒకరు రాజ్యానికొచ్చారు.","table":null},{"a":"30 సంవత్సరాలు","e":"ఇతని అధికారం కళింగం నుండి పాకనాటి వరకు సాగింది.","table":null},{"a":"విక్రమాదిత్యుడు","e":"ఇతని దండయాత్రలలో జయసింహుడు సహాయపడ్డాడు.","table":null},{"a":"రెండవ విష్ణువర్ధనుడు","e":"ఇతను ఇంద్రభట్టారకుని కుమారుడు, తొమ్మిది సంవత్సరాలు పరిపాలించాడు.","table":null},{"a":"యునిత్సాంగ్","e":"అప్పటికి ఈ ప్రాంతంలో బౌద్ధమతం క్షీణదశలో ఉందని ఇతను పేర్కొన్నాడు.","table":null},{"a":"20","e":"","table":null},{"a":"మూడువేలమంది","e":"","table":null},{"a":"ఇరవై అయిదేళ్ళు","e":"","table":null},{"a":"జయసింహుడు","e":"మంగిరాజు తరువాత జయసింహుడు, తర్వాత కొక్కిలి విక్రమాదిత్యుడు, తర్వాత ముమ్మడి విష్ణువర్ధనుడు వరుసగా పరిపాలించారు.","table":{"headers":["పాలకుడు","పాలన ప్రారంభం","పాలన ముగింపు"],"rows":[["జయసింహుడు","705","712"],["కొక్కిలి విక్రమాదిత్యుడు","712","718"],["ముమ్మడి విష్ణువర్ధనుడు","718","752"]],"unit":"క్రీ.శ."}},{"a":"రెండవ కీర్తివర్మ","e":"","table":null},{"a":"ప్రధాన కర్తవ్యం","e":"","table":null},{"a":"క్రీ.శ. 755","e":"","table":null},{"a":"కృష్టుడు","e":"","table":null},{"a":"771 నుండి 804 వరకు","e":"","table":null},{"a":"శిలామహాదేవి","e":"","table":null},{"a":"భీమసలుడు","e":"ఇతనికి రాష్ట్రకూట చక్రవర్తి ముమ్మడి గోవిందరాజు సహాయపడ్డాడు.","table":null},{"a":"తొమ్మిది సంవత్సరాలు","e":"","table":null},{"a":"నూటయెనిమిది","e":"ఇతను మహేశ్వర భక్తుడు.","table":null},{"a":"784","e":"","table":null},{"a":"పద్దెనిమిది మాసాలు","e":"","table":null},{"a":"44 సంవత్సరాలు","e":"","table":null},{"a":"కర్నూలు","e":"ఈ ఓటమి తాత్కాలికమే, తరువాత గంగరాజుల సహాయంతో తిరిగి రాజ్యాన్ని స్వాధీనపరచుకున్నాడు.","table":null},{"a":"చాళుక్య భీముడు","e":"","table":null},{"a":"కళింగ యుద్ధంలో, 921లో","e":"","table":null},{"a":"రెండవ చాళుక్యభీముడు","e":"","table":null},{"a":"చోళచక్రవర్తి రాజరాజు","e":"వారి కుమారుడే రాజరాజ నరేంద్రుడు.","table":null},{"a":"రాజేంద్రుడు","e":"ఇతడు మాతామహుని వద్ద చోళరాజధానిలో పెరిగాడు.","table":null},{"a":"పినతండ్రి విజయాదిత్యునికి","e":"రాజేంద్రునికి కాకుండా విజయాదిత్యునికి లభించింది.","table":null},{"a":"రాజేంద్రుడు ద్రవిడదేశంలో స్థిరపడటం","e":"అతడు చోళరాజ్యాన్నే తన జన్మరాజ్యంగా భావించుకున్నాడు.","table":null},{"a":"నాడులు, విషయములుగా","e":"","table":null},{"a":"రాజమహేంద్రవరం, వేంగీపురం","e":"వేంగీపురం ఇప్పుడు పశ్చిమగోదావరి జిల్లా ఏలూరు పట్టణానికి ఎనిమిది మైళ్ళ దూరంలో శిథిలావస్థలో కనిపిస్తుంది.","table":null},{"a":"వేగినాథ, వేగి భూవల్లభ","e":"","table":null},{"a":"రాజు","e":"","table":null},{"a":"మంత్రి","e":"","table":null},{"a":"రాజు ఇష్టం","e":"","table":null},{"a":"ముఖ్యమైన ఆదాయం","e":"","table":null},{"a":"భూసారం లెక్క","e":"భూసారాన్ని లెక్కకు తీసుకుని పన్నులు విధించేవారు.","table":null},{"a":"ఇంటిపన్ను, వృత్తిపన్ను, వివాహపండిల్లు","e":"ఇంటిపన్ను, వృత్తిపన్ను, వివాహపండిళ్ళపై పన్ను చెల్లించాల్సి వచ్చేది.","table":null},{"a":"వేదవిదులైన విప్రులు","e":"పశువుల మేతకు కేటాయించిన బీళ్ళపై కూడా సుంకాలు లేవు.","table":null},{"a":"పంచాయతీ వ్యవస్థ","e":"గ్రామపంచాయతీ సభ్యులను రాజులే నియమించేవారు.","table":null},{"a":"వేదశాస్త్రపారంగతులు, నిత్యసత్యవ్రతులు","e":"ధార్మికులు, ధీరులు, లౌకికులు, పలుకుబడి కలవారు, మిత్రామిత్రుల యెడల సమదృష్టి ప్రదర్శించేవారు అర్హులు.","table":null},{"a":"కొలపాత్రలు","e":"","table":null},{"a":"సామంతులు, మాండలికులు","e":"","table":null},{"a":"వీరపానము","e":"","table":null},{"a":"స్త్రీలు","e":"","table":null},{"a":"కవచాలు","e":"సైనికులు శిరస్త్రాణము, కవచములు ధరించేవారు.","table":null},{"a":"స్త్రీ, శిశు, బాల, బ్రాహ్మణ, వృద్ధ జనులు","e":"","table":null},{"a":"వైదిక మతావలంబులు","e":"వీరు శివపూజా ధురంధరులు, శైవమతాలను, శైవాగమ శాస్త్రవేత్తలను పోషించేవారు.","table":null},{"a":"జైనులు","e":"కాబట్టి ఆంధ్రదేశంలో మొదట జైనశిల్పం తీసుకువచ్చినది వీరే. బసవేశ్వరుని శకం పూర్తికాగానే చాళుక్యులు శివదీక్షాపరులైనారు.","table":null},{"a":"వరాహ చిహ్నాలు","e":"దీని అర్థం రాజులు వైష్ణవులని కాదు; రాజులు శాసనాలపై శివలింగాన్ని, చంద్రుని గుర్తును వేసేవారు, చాళుక్య రాజులు శైవ మతస్థులు.","table":null},{"a":"రాజు తల్లి","e":"","table":null},{"a":"కృష్టుడు","e":"ఇతను రాష్ట్రకూట రాజు.","table":null},{"a":"మాల్ఖేడ్","e":"","table":null},{"a":"శాలివాహనులకు","e":"తరువాత పశ్చిమ చాళుక్యులకు సామంతులైనారు.","table":null},{"a":"దంతిదుర్గుడు","e":"","table":null},{"a":"కుష్ఠురోగం","e":"","table":null},{"a":"ఎల్లోరా కొండలవద్దనున్న నూతిలోని జలం స్వీకరించమని","e":"రాజు అలాగే చేయగా రోగం నిశ్శేషంగా తగ్గింది.","table":null},{"a":"కైలాసమూర్తి శిల్పరూపం","e":"ఈశ్వరునికి అంకితం ఇవ్వడానికి సంకల్పించాడు.","table":null},{"a":"అజంతా, మహాబలిపురం శిల్పుల వంశీకులు","e":"వీరు ఆంధ్రశిల్పులు.","table":null},{"a":"ఒక్క రాయి నుండి","e":"గుడి, గుడిచుట్టు మందిరాలు, గోడలు, మండపాలు, ధ్వజస్తంభాలు అంతా ఒకే రాతిలో చెక్కిన శిల్పం.","table":null},{"a":"రావణుడు కైలాసాన్ని ఎత్తడానికి సంకల్పించడం","e":"హిరణ్యకశిపుని మదమణచుటకు అతనితో కుస్తీ పడుతున్న సింహమూర్తి చిత్రితమైంది.","table":null},{"a":"ప్రభావతిగుప్త","e":"ఈమె వైశ్య కన్య, ఇది కులాంతర వివాహానికి ఉదాహరణ.","table":null},{"a":"ద్రావిడ భాషలు","e":"","table":null},{"a":"నన్నయ భట్టారకుడు","e":"ఇతను రాజరాజనరేంద్రుని కాలంలో రచించాడు.","table":null},{"a":"నన్నెచోడుడు","e":"ఇతను భారత రచనలో తనకు నారాయణభట్టు సహకరించినట్టు చెప్పుకున్నాడు.","table":null},{"a":"గ్రంథరూపం","e":"","table":null},{"a":"గొప్పస్థానం","e":"రాగిరేకులపై శాసనాలు చెక్కడం వీరిపని, శాసన లేఖకులుగా విశ్వకర్మ కులస్థులను నియమించేవారు.","table":null},{"a":"నాలుగు రోజులు","e":"స్త్రీ మెట్టెలు ధరించేవారు, మేనమరదిని పెళ్ళి చేసుకునే ఆచారం ఉండేది.","table":null},{"a":"తూర్పు చాళుక్య వంశం","e":"క్రీ.శ. 625 నుండి 1070 వరకు సుమారు నాలుగు శతాబ్దాలు తెలుగుదేశాన్ని పాలించారు.","table":null},{"a":"చాళుక్యులను","e":"","table":null},{"a":"కొరవి శాసనం","e":"ఇది కీ.శ. 892-921 నాటిది, కొరవి మానుకోట ప్రాంతంలో ఉంది.","table":null},{"a":"చక్రటి వచనం","e":"","table":null}]') ON CONFLICT(chapter_slug) DO UPDATE SET subject_id=excluded.subject_id, chapter_number=excluded.chapter_number, title=excluded.title, answers_json=excluded.answers_json;
INSERT INTO chapter_content (chapter_slug, subject_id, chapter_number, title, answers_json) VALUES ('chapter-5-kakatiyulu', 'telangana-history-te', 5, 'కాకతీయులు', '[{"a":"బేతరాజు","e":"ఇతను సీమ (మధుర), కారివిసీమ (దోర్నకల్) మండలాధిపతి.","table":null},{"a":"క్రీ.శ. 1000 నుండి 1050 వరకు","e":"","table":null},{"a":"తూర్పు చాళుక్యులకు","e":"పిమ్మట పశ్చిమ చాళుక్యులకు సామంతులైనారు.","table":null},{"a":"మొదటి ప్రోలరాజు","e":"","table":null},{"a":"ఖాజీపేట శాసనం","e":"","table":null},{"a":"క్రీ.శ. 1050 నుండి 1080 వరకు","e":"","table":null},{"a":"త్రిభువనమల్ల","e":"ఇతను పరాక్రమవంతుడు.","table":null},{"a":"రెండవ ప్రోలరాజు","e":"","table":null},{"a":"పశ్చిమ చాళుక్యరాజు విక్రమాదిత్యుని మరణానంతరం","e":"","table":null},{"a":"క్రీ.శ. 1115 నుండి 1158 వరకు","e":"","table":null},{"a":"1158-1195","e":"","table":null},{"a":"ఓరుగల్లు కోట","e":"","table":null},{"a":"నీతిసారము","e":"దీనికిగాను ఇతను విద్యాభూషణ బిరుదు పొందాడు.","table":null},{"a":"దేవగిరి రాజు","e":"","table":null},{"a":"1195 నుండి 1199 వరకు","e":"","table":null},{"a":"1199-1261","e":"","table":null},{"a":"యాదవరాజు చెరసాలలో","e":"","table":null},{"a":"1208","e":"","table":null},{"a":"రుద్రసేనాని","e":"","table":null},{"a":"ఉత్తర గోండ్వానా నుండి దక్షిణాన కాంచీవరకు, తూర్పు బంగాళాఖాతం నుండి పశ్చిమాన బీదరు వరకు","e":"","table":null},{"a":"గణపతిదేవ చక్రవర్తి","e":"","table":null},{"a":"ఓరుగల్లు","e":"అంతవరకు వారి రాజధాని హనుమకొండ.","table":null},{"a":"కర్షకులు, రెడ్డి, వెలమ, కమ్మ, బ్రాహ్మణ కులాలు","e":"","table":null},{"a":"ఓరుగల్లు","e":"గణపతిదేవుని ఆస్థానంలోనే పూర్తి చేశాడు.","table":null},{"a":"1262-1296","e":"","table":null},{"a":"పుత్రసంతానం లేనందున","e":"కుమార్తె రుద్రమదేవి రాణి అయింది.","table":null},{"a":"మార్కోపోలో","e":"","table":null},{"a":"పురుషవేషం","e":"","table":null},{"a":"రుద్రమదేవి మహారాజు","e":"","table":null},{"a":"యాదవరాజు","e":"","table":null},{"a":"ముమ్మడమ్మ, రాయనమ్మ","e":"ముమ్మడమ్మ కుమారుడే రెండవ ప్రతాపరుద్రదేవుడు.","table":null},{"a":"1296-1323","e":"","table":null},{"a":"1296","e":"","table":null},{"a":"